const HABIT_PALETTES = [
  { color: '#60a5fa', glow: 'rgba(96, 165, 250, 0.45)', name: 'Sky' },
  { color: '#facc15', glow: 'rgba(250, 204, 21, 0.45)', name: 'Amber' },
  { color: '#fb7185', glow: 'rgba(251, 113, 133, 0.45)', name: 'Rose' },
  { color: '#2dd4bf', glow: 'rgba(45, 212, 191, 0.45)', name: 'Teal' },
  { color: '#818cf8', glow: 'rgba(129, 140, 248, 0.45)', name: 'Indigo' },
  { color: '#c084fc', glow: 'rgba(192, 132, 252, 0.45)', name: 'Purple' },
  { color: '#fb923c', glow: 'rgba(251, 146, 60, 0.45)', name: 'Coral' },
  { color: '#34d399', glow: 'rgba(52, 211, 153, 0.45)', name: 'Emerald' },
]

function getHabitYearGrid(
  seedId: string,
  basePct: number = 0,
  isDoneToday?: boolean,
  completedDates?: string[],
  schedule?: string[],
  isSkippedToday?: boolean
) {
  const TOTAL_WEEKS = 42
  const TOTAL_DAYS = TOTAL_WEEKS * 7 // 294 days

  const uniqueDates = new Set<string>(completedDates || [])
  const now = new Date()
  const todayLocal = new Date(now.getFullYear(), now.getMonth(), now.getDate())
  const todayIso = getLocalIsoDate(todayLocal)

  // Sumber kebenaran utama adalah completedDates; hanya sinkronkan todayIso jika isDoneToday eksplisit
  if (isDoneToday === true) {
    uniqueDates.add(todayIso)
  } else if (isDoneToday === false) {
    uniqueDates.delete(todayIso)
  }

  const isScheduledDay = (d: Date) => {
    if (!schedule || schedule.length === 0 || schedule.includes('Everyday')) return true
    return schedule.includes(DAY_CODES_GLOBAL[d.getDay()])
  }

  // Hitung streak berturut-turut (dalam satuan hari) & tandai tanggal yang termasuk active streak
  const streakDates = new Set<string>()
  let streakDays = 0

  if (uniqueDates.has(todayIso)) {
    streakDates.add(todayIso)
    streakDays = 1
    for (let offset = 1; offset <= 365; offset++) {
      const d = new Date(todayLocal)
      d.setDate(todayLocal.getDate() - offset)
      const dIso = getLocalIsoDate(d)
      if (uniqueDates.has(dIso)) {
        streakDates.add(dIso)
        streakDays++
      } else if (isScheduledDay(d)) {
        break
      }
    }
  } else if (!isSkippedToday) {
    // Hari ini belum dikerjakan (dan tidak di-skip): cek apakah streak hingga hari terjadwal terakhir masih aktif
    for (let offset = 1; offset <= 365; offset++) {
      const d = new Date(todayLocal)
      d.setDate(todayLocal.getDate() - offset)
      const dIso = getLocalIsoDate(d)
      if (uniqueDates.has(dIso)) {
        streakDates.add(dIso)
        streakDays++
      } else if (isScheduledDay(d)) {
        break
      }
    }
  }

  // Tentukan Senin dari minggu awal (berdasarkan tanggal paling awal atau minggu ini)
  const todayMonIdx = (todayLocal.getDay() + 6) % 7 // Mon=0 .. Sun=6
  const thisWeekMonday = new Date(todayLocal)
  thisWeekMonday.setDate(todayLocal.getDate() - todayMonIdx)

  let startMonday = new Date(thisWeekMonday)
  if (uniqueDates.size > 0) {
    const sorted = Array.from(uniqueDates).sort()
    const earliestParts = sorted[0].split('-').map(Number)
    if (earliestParts.length === 3 && !earliestParts.some(isNaN)) {
      const earliestDate = new Date(earliestParts[0], earliestParts[1] - 1, earliestParts[2])
      const earliestMonIdx = (earliestDate.getDay() + 6) % 7
      const earliestMonday = new Date(earliestDate)
      earliestMonday.setDate(earliestDate.getDate() - earliestMonIdx)
      if (earliestMonday < startMonday) {
        startMonday = earliestMonday
      }
    }
  }

  // Jika rentang melebihi 42 minggu, geser window agar minggu ini tetap terlihat di akhir
  const diffDays = Math.round((thisWeekMonday.getTime() - startMonday.getTime()) / 86400000)
  if (diffDays + 7 > TOTAL_DAYS) {
    startMonday = new Date(thisWeekMonday)
    startMonday.setDate(thisWeekMonday.getDate() - (TOTAL_WEEKS - 1) * 7)
  }

  const cells: ('streak' | 'done' | 'inactive' | 'unscheduled' | 'future')[] = []
  const cellDates: string[] = []

  for (let day = 0; day < TOTAL_DAYS; day++) {
    const cellDate = new Date(startMonday)
    cellDate.setDate(startMonday.getDate() + day)
    const cellIso = getLocalIsoDate(cellDate)
    cellDates.push(cellIso)

    if (uniqueDates.has(cellIso)) {
      cells.push(streakDates.has(cellIso) ? 'streak' : 'done')
    } else if (!isScheduledDay(cellDate)) {
      cells.push('unscheduled')
    } else if (cellIso > todayIso) {
      cells.push('future')
    } else {
      cells.push('inactive')
    }
  }

  return { cells, cellDates, streakDays, pct: streakDays }
}

