  const urlBase64ToUint8Array = (base64String: string) => {
    const padding = '='.repeat((4 - (base64String.length % 4)) % 4)
    const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/')
    const rawData = window.atob(base64)
    const outputArray = new Uint8Array(rawData.length)
    for (let i = 0; i < rawData.length; ++i) {
      outputArray[i] = rawData.charCodeAt(i)
    }
    return outputArray
  }

  const [arrivedQuestAlert, setArrivedQuestAlert] = useState<PersonalTask | null>(null)
  const [pendingQuestAlertCount, setPendingQuestAlertCount] = useState<number>(0)
  const [isClosingQuestAlert, setIsClosingQuestAlert] = useState<boolean>(false)
  const [questAlertAnimKey, setQuestAlertAnimKey] = useState<number>(0)
  const [isQuestAlertSealed, setIsQuestAlertSealed] = useState<boolean>(false)
  const [isAudioAutoplayBlocked, setIsAudioAutoplayBlocked] = useState<boolean>(false)
  const hasUserInteractedRef = useRef<boolean>(false)
  const audioCtxRef = useRef<AudioContext | null>(null)
  const pendingArrivalSoundRef = useRef<boolean>(false)
  const sfxWavUrlsRef = useRef<{ open?: string; accept?: string; skip?: string }>({})
  const sfxAudioElRef = useRef<HTMLAudioElement | null>(null)

  // Encode AudioBuffer menjadi WAV Blob URL agar bisa diputar via HTML5 <audio>
  // (Di iOS/iPhone PWA, <audio> memakai kanal Media sehingga tetap berbunyi meski tombol silent fisik aktif)
  const encodeAudioBufferToWavUrl = (buffer: AudioBuffer): string => {
    const numChannels = 1
    const sampleRate = buffer.sampleRate
    const samples = buffer.getChannelData(0)
    const byteLength = 44 + samples.length * 2
    const arrayBuffer = new ArrayBuffer(byteLength)
    const view = new DataView(arrayBuffer)
    const writeStr = (offset: number, str: string) => {
      for (let i = 0; i < str.length; i++) view.setUint8(offset + i, str.charCodeAt(i))
    }
    writeStr(0, 'RIFF')
    view.setUint32(4, byteLength - 8, true)
    writeStr(8, 'WAVE')
    writeStr(12, 'fmt ')
    view.setUint32(16, 16, true)
    view.setUint16(20, 1, true)
    view.setUint16(22, numChannels, true)
    view.setUint32(24, sampleRate, true)
    view.setUint32(28, sampleRate * numChannels * 2, true)
    view.setUint16(32, numChannels * 2, true)
    view.setUint16(34, 16, true)
    writeStr(36, 'data')
    view.setUint32(40, samples.length * 2, true)
    let offset = 44
    for (let i = 0; i < samples.length; i++) {
      const s = Math.max(-1, Math.min(1, samples[i]))
      view.setInt16(offset, s < 0 ? s * 0x8000 : s * 0x7fff, true)
      offset += 2
    }
    return URL.createObjectURL(new Blob([arrayBuffer], { type: 'audio/wav' }))
  }

  // Helper internal: sintesis suara Solo Leveling System Window Open (telemetry HUD + sub drop + cold FM ping)
  const renderQuestOpenSfx = (ctx: BaseAudioContext) => {
    const now = ctx.currentTime + 0.01

    const master = ctx.createGain()
    master.gain.setValueAtTime(0.88, now)
    master.connect(ctx.destination)

    // Dark holographic delay tail (95ms)
    const delay = ctx.createDelay(0.5)
    delay.delayTime.setValueAtTime(0.095, now)
    const fb = ctx.createGain()
    fb.gain.setValueAtTime(0.26, now)
    const echoFilter = ctx.createBiquadFilter()
    echoFilter.type = 'lowpass'
    echoFilter.frequency.setValueAtTime(2200, now)
    delay.connect(echoFilter)
    echoFilter.connect(fb)
    fb.connect(delay)
    echoFilter.connect(master)

    // 1. Digital HUD Telemetry Ignition (0.00s - 0.06s): 3 micro-data pulses (1840, 1420, 1960 Hz)
    const hudBand = ctx.createBiquadFilter()
    hudBand.type = 'bandpass'
    hudBand.frequency.setValueAtTime(1800, now)
    hudBand.Q.setValueAtTime(2.8, now)
    hudBand.connect(master)

    ;[1840, 1420, 1960].forEach((freq, idx) => {
      const t0 = now + idx * 0.02
      const sq = ctx.createOscillator()
      const g = ctx.createGain()
      sq.type = 'square'
      sq.frequency.setValueAtTime(freq, t0)
      g.gain.setValueAtTime(0.001, t0)
      g.gain.linearRampToValueAtTime(0.14, t0 + 0.003)
      g.gain.exponentialRampToValueAtTime(0.001, t0 + 0.015)
      sq.connect(g)
      g.connect(hudBand)
      sq.start(t0)
      sq.stop(t0 + 0.018)
    })

    // 2. Dark Hologram Shutter Sweep & Sub-Gravity Drop (0.03s - 0.36s)
    const sub = ctx.createOscillator()
    const subGain = ctx.createGain()
    sub.type = 'sine'
    sub.frequency.setValueAtTime(115, now + 0.03)
    sub.frequency.exponentialRampToValueAtTime(44, now + 0.36)
    subGain.gain.setValueAtTime(0.001, now + 0.03)
    subGain.gain.linearRampToValueAtTime(0.36, now + 0.07)
    subGain.gain.exponentialRampToValueAtTime(0.001, now + 0.42)
    sub.connect(subGain)
    subGain.connect(master)
    sub.start(now + 0.03)
    sub.stop(now + 0.44)

    const bufLen = Math.floor(ctx.sampleRate * 0.34)
    const noiseBuf = ctx.createBuffer(1, bufLen, ctx.sampleRate)
    const ch = noiseBuf.getChannelData(0)
    for (let i = 0; i < bufLen; i++) {
      ch[i] = (Math.random() * 2 - 1) * Math.sin((i / bufLen) * Math.PI)
    }
    const noise = ctx.createBufferSource()
    noise.buffer = noiseBuf
    const bp = ctx.createBiquadFilter()
    bp.type = 'bandpass'
    bp.frequency.setValueAtTime(240, now + 0.03)
    bp.frequency.exponentialRampToValueAtTime(1450, now + 0.17)
    bp.frequency.exponentialRampToValueAtTime(360, now + 0.36)
    bp.Q.setValueAtTime(4.2, now + 0.03)
    const nGain = ctx.createGain()
    nGain.gain.setValueAtTime(0.001, now + 0.03)
    nGain.gain.linearRampToValueAtTime(0.24, now + 0.12)
    nGain.gain.exponentialRampToValueAtTime(0.001, now + 0.36)
    noise.connect(bp)
    bp.connect(nGain)
    nGain.connect(master)
    noise.start(now + 0.03)

    // 3. Cold Metallic FM System Ping (0.13s - 0.82s, Dark Phrygian/Minor Tension)
    const triggerFmMetallicPing = (
      freq: number,
      startOffset: number,
      dur: number,
      vol: number,
      sendDelay = true
    ) => {
      const t0 = now + startOffset
      const carrier = ctx.createOscillator()
      const mod = ctx.createOscillator()
      const modGain = ctx.createGain()
      const env = ctx.createGain()

      carrier.type = 'sine'
      mod.type = 'sine'
      carrier.frequency.setValueAtTime(freq, t0)
      mod.frequency.setValueAtTime(freq * 1.414, t0)

      // Fast modulator envelope for crisp metallic glass transient
      modGain.gain.setValueAtTime(freq * 0.85, t0)
      modGain.gain.exponentialRampToValueAtTime(4, t0 + Math.min(0.16, dur * 0.6))

      env.gain.setValueAtTime(0.001, t0)
      env.gain.linearRampToValueAtTime(vol, t0 + 0.008)
      env.gain.exponentialRampToValueAtTime(0.001, t0 + dur)

      mod.connect(modGain)
      modGain.connect(carrier.frequency)
      carrier.connect(env)
      env.connect(master)
      if (sendDelay) env.connect(delay)

      carrier.start(t0)
      mod.start(t0)
      carrier.stop(t0 + dur + 0.02)
      mod.stop(t0 + dur + 0.02)
    }

    // Note 1 (0.13s): crisp C5 tactical alert pulse (0.08s)
    triggerFmMetallicPing(523.25, 0.13, 0.09, 0.22, false)
    // Note 2 (0.21s): authoritative semitone drop B4 + cold octave B5 + deep grounding fifth E4
    triggerFmMetallicPing(493.88, 0.21, 0.61, 0.24, true)
    triggerFmMetallicPing(987.77, 0.21, 0.56, 0.14, true)
    triggerFmMetallicPing(329.63, 0.21, 0.61, 0.16, true)

    if (typeof navigator !== 'undefined' && navigator.vibrate) {
      navigator.vibrate([45, 30, 95])
    }
  }

  // Pre-render WAV untuk suara System Open (agar bisa diputar via HTML5 <audio> di iOS/Android PWA)
  useEffect(() => {
    if (typeof window === 'undefined') return
    const OfflineCtx = window.OfflineAudioContext || (window as any).webkitOfflineAudioContext
    if (!OfflineCtx) return
    let cancelled = false
    const bake = async () => {
      try {
        const sampleRate = 22050
        const openCtx = new OfflineCtx(1, Math.floor(sampleRate * 1.15), sampleRate)
        renderQuestOpenSfx(openCtx)
        const openBuf = await openCtx.startRendering()
        if (!cancelled) {
          sfxWavUrlsRef.current.open = encodeAudioBufferToWavUrl(openBuf)
        }
      } catch {}
    }
    bake()
    return () => {
      cancelled = true
    }
  }, [])

  // Helper internal: putar suara Open via HTML5 <audio> (iOS-friendly) dengan fallback Web Audio API
  const playOpenAudioElement = (): Promise<boolean> => {
    return new Promise((resolve) => {
      try {
        const wavUrl = sfxWavUrlsRef.current.open
        if (!wavUrl) {
          resolve(false)
          return
        }
        const el = sfxAudioElRef.current || new Audio()
        sfxAudioElRef.current = el
        el.src = wavUrl
        el.volume = 1
        el.currentTime = 0
        const p = el.play()
        if (p && typeof p.then === 'function') {
          p.then(() => {
            setIsAudioAutoplayBlocked(false)
            resolve(true)
          }).catch(() => {
            resolve(false)
          })
        } else {
          setIsAudioAutoplayBlocked(false)
          resolve(true)
        }
      } catch {
        resolve(false)
      }
    })
  }

  // Unlock permanen AudioContext + HTML5 Audio (khususnya iOS Safari PWA) pada sentuhan pertama
  useEffect(() => {
    const unlock = () => {
      try {
        if (typeof window === 'undefined') return
        hasUserInteractedRef.current = true
        if (pendingArrivalSoundRef.current && prefSound) {
          pendingArrivalSoundRef.current = false
          setIsAudioAutoplayBlocked(false)
          playOpenAudioElement().then((played) => {
            if (!played) {
              const AudioCtx = window.AudioContext || (window as any).webkitAudioContext
              if (!AudioCtx) return
              const ctx = audioCtxRef.current || new AudioCtx()
              audioCtxRef.current = ctx
              if (ctx.state === 'suspended') {
                ctx.resume().then(() => renderQuestOpenSfx(ctx)).catch(() => {})
              } else {
                renderQuestOpenSfx(ctx)
              }
            }
          })
          return
        }

        const AudioCtx = window.AudioContext || (window as any).webkitAudioContext
        if (!AudioCtx) return
        if (!audioCtxRef.current) {
          audioCtxRef.current = new AudioCtx()
        }
        const ctx = audioCtxRef.current
        const silentBuf = ctx.createBuffer(1, 1, 22050)
        const src = ctx.createBufferSource()
        src.buffer = silentBuf
        src.connect(ctx.destination)
        src.start(0)
        if (ctx.state === 'suspended') {
          ctx.resume().catch(() => {})
        }
      } catch {}
    }
    window.addEventListener('touchstart', unlock, { passive: true })
    window.addEventListener('pointerdown', unlock, { passive: true })
    window.addEventListener('keydown', unlock, { passive: true })
    return () => {
      window.removeEventListener('touchstart', unlock)
      window.removeEventListener('pointerdown', unlock)
      window.removeEventListener('keydown', unlock)
    }
  }, [prefSound])

  // Efek suara RPG / Shadow Monarch System saat Pop-Up Quest Muncul & Kebuka
  const playQuestArrivalSound = () => {
    try {
      if (!prefSound || typeof window === 'undefined') return
      playOpenAudioElement().then((played) => {
        if (played) {
          pendingArrivalSoundRef.current = false
          setIsAudioAutoplayBlocked(false)
          if (typeof navigator !== 'undefined' && navigator.vibrate) {
            navigator.vibrate([45, 30, 95])
          }
          return
        }
        // Fallback Web Audio API
        const AudioCtx = window.AudioContext || (window as any).webkitAudioContext
        if (!AudioCtx) {
          pendingArrivalSoundRef.current = true
          setIsAudioAutoplayBlocked(true)
          return
        }
        const ctx = audioCtxRef.current || new AudioCtx()
        audioCtxRef.current = ctx
        if (ctx.state === 'running') {
          pendingArrivalSoundRef.current = false
          setIsAudioAutoplayBlocked(false)
          renderQuestOpenSfx(ctx)
        } else {
          pendingArrivalSoundRef.current = true
          setIsAudioAutoplayBlocked(true)
          ctx
            .resume()
            .then(() => {
              if (ctx.state === 'running' && pendingArrivalSoundRef.current) {
                pendingArrivalSoundRef.current = false
                setIsAudioAutoplayBlocked(false)
                renderQuestOpenSfx(ctx)
              }
            })
            .catch(() => {})
        }
      })
    } catch (e) {
      console.error(e)
    }
  }

  // Efek suara Dark Tactical Solo Leveling "QUEST ACCEPTED" saat tombol TERIMA QUEST ditekan
  const playQuestAcceptSound = () => {
    try {
      if (!prefSound || typeof window === 'undefined') return
      pendingArrivalSoundRef.current = false
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext
      if (!AudioCtx) return
      const ctx = audioCtxRef.current || new AudioCtx()
      audioCtxRef.current = ctx

      const trigger = () => {
        const now = ctx.currentTime + 0.005
        const master = ctx.createGain()
        master.gain.setValueAtTime(0.9, now)
        master.connect(ctx.destination)

      // Dark abyssal delay tail
      const delay = ctx.createDelay(0.5)
      delay.delayTime.setValueAtTime(0.115, now)
      const fb = ctx.createGain()
      fb.gain.setValueAtTime(0.28, now)
      const dFilter = ctx.createBiquadFilter()
      dFilter.type = 'lowpass'
      dFilter.frequency.setValueAtTime(1900, now)
      delay.connect(dFilter)
      dFilter.connect(fb)
      fb.connect(delay)
      dFilter.connect(master)

      // 1. Heavy Seismic Sub-Drop & Mechanical Lock (0.00s - 0.26s)
      const impact = ctx.createOscillator()
      const impactGain = ctx.createGain()
      impact.type = 'sine'
      impact.frequency.setValueAtTime(150, now)
      impact.frequency.exponentialRampToValueAtTime(36, now + 0.24)
      impactGain.gain.setValueAtTime(0.48, now)
      impactGain.gain.exponentialRampToValueAtTime(0.001, now + 0.27)
      impact.connect(impactGain)
      impactGain.connect(master)
      impact.start(now)
      impact.stop(now + 0.29)

      // Short 45ms bandpass-filtered metallic lock transient (1550 Hz)
      const lockBufLen = Math.floor(ctx.sampleRate * 0.05)
      const lockBuf = ctx.createBuffer(1, lockBufLen, ctx.sampleRate)
      const lockCh = lockBuf.getChannelData(0)
      for (let i = 0; i < lockBufLen; i++) {
        lockCh[i] = (Math.random() * 2 - 1) * (1 - i / lockBufLen)
      }
      const lockNoise = ctx.createBufferSource()
      lockNoise.buffer = lockBuf
      const lockBp = ctx.createBiquadFilter()
      lockBp.type = 'bandpass'
      lockBp.frequency.setValueAtTime(1550, now)
      lockBp.Q.setValueAtTime(4.5, now)
      const lockNoiseGain = ctx.createGain()
      lockNoiseGain.gain.setValueAtTime(0.32, now)
      lockNoiseGain.gain.exponentialRampToValueAtTime(0.001, now + 0.045)
      lockNoise.connect(lockBp)
      lockBp.connect(lockNoiseGain)
      lockNoiseGain.connect(master)
      lockNoise.start(now)

      // FM metallic clank (780 Hz -> 290 Hz)
      const clankCarrier = ctx.createOscillator()
      const clankMod = ctx.createOscillator()
      const clankModGain = ctx.createGain()
      const clankGain = ctx.createGain()
      clankCarrier.type = 'triangle'
      clankMod.type = 'sine'
      clankCarrier.frequency.setValueAtTime(780, now)
      clankCarrier.frequency.exponentialRampToValueAtTime(290, now + 0.09)
      clankMod.frequency.setValueAtTime(780 * 1.414, now)
      clankModGain.gain.setValueAtTime(420, now)
      clankModGain.gain.exponentialRampToValueAtTime(5, now + 0.08)
      clankGain.gain.setValueAtTime(0.24, now)
      clankGain.gain.exponentialRampToValueAtTime(0.001, now + 0.11)
      clankMod.connect(clankModGain)
      clankModGain.connect(clankCarrier.frequency)
      clankCarrier.connect(clankGain)
      clankGain.connect(master)
      clankCarrier.start(now)
      clankMod.start(now)
      clankCarrier.stop(now + 0.12)
      clankMod.stop(now + 0.12)

      // 2. Tactical Data-Lock Confirm Pulses (0.03s - 0.12s): B5 -> F#5 -> E5 (22ms each)
      const pulseBand = ctx.createBiquadFilter()
      pulseBand.type = 'bandpass'
      pulseBand.frequency.setValueAtTime(1250, now)
      pulseBand.Q.setValueAtTime(2.0, now)
      pulseBand.connect(master)

      ;[987.77, 739.99, 659.25].forEach((freq, idx) => {
        const t0 = now + 0.03 + idx * 0.03
        const osc = ctx.createOscillator()
        const g = ctx.createGain()
        osc.type = 'square'
        osc.frequency.setValueAtTime(freq, t0)
        g.gain.setValueAtTime(0.001, t0)
        g.gain.linearRampToValueAtTime(0.14, t0 + 0.004)
        g.gain.exponentialRampToValueAtTime(0.001, t0 + 0.022)
        osc.connect(g)
        g.connect(pulseBand)
        osc.start(t0)
        osc.stop(t0 + 0.026)
      })

      // 3. Shadow Monarch Dark Reese Power Surge (0.08s - 0.95s): open dark fifths E2 + B2 + E3
      const reeseFilter = ctx.createBiquadFilter()
      reeseFilter.type = 'lowpass'
      reeseFilter.frequency.setValueAtTime(1100, now + 0.08)
      reeseFilter.frequency.exponentialRampToValueAtTime(210, now + 0.95)
      reeseFilter.Q.setValueAtTime(3.5, now + 0.08)

      const reeseGain = ctx.createGain()
      reeseGain.gain.setValueAtTime(0.001, now + 0.08)
      reeseGain.gain.linearRampToValueAtTime(0.16, now + 0.15)
      reeseGain.gain.exponentialRampToValueAtTime(0.001, now + 0.95)
      reeseFilter.connect(reeseGain)
      reeseGain.connect(master)
      reeseGain.connect(delay)

      ;[82.41, 123.47, 164.81].forEach((f) => {
        ;[-9, 9].forEach((detuneCents) => {
          const s = ctx.createOscillator()
          s.type = 'sawtooth'
          s.frequency.setValueAtTime(f, now + 0.08)
          s.detune.setValueAtTime(detuneCents, now + 0.08)
          s.connect(reeseFilter)
          s.start(now + 0.08)
          s.stop(now + 0.98)
        })
      })

      // Single cold metallic FM E5 lock-in tone (0.14s - 0.85s)
      const lockCarrier = ctx.createOscillator()
      const lockMod = ctx.createOscillator()
      const lockModGain = ctx.createGain()
      const lockToneGain = ctx.createGain()
      lockCarrier.type = 'sine'
      lockMod.type = 'sine'
      lockCarrier.frequency.setValueAtTime(659.25, now + 0.14) // E5
      lockMod.frequency.setValueAtTime(659.25 * 1.414, now + 0.14)
      lockModGain.gain.setValueAtTime(480, now + 0.14)
      lockModGain.gain.exponentialRampToValueAtTime(3, now + 0.28)
      lockToneGain.gain.setValueAtTime(0.001, now + 0.14)
      lockToneGain.gain.linearRampToValueAtTime(0.2, now + 0.15)
      lockToneGain.gain.exponentialRampToValueAtTime(0.001, now + 0.88)
      lockMod.connect(lockModGain)
      lockModGain.connect(lockCarrier.frequency)
      lockCarrier.connect(lockToneGain)
      lockToneGain.connect(master)
      lockToneGain.connect(delay)
      lockCarrier.start(now + 0.14)
      lockMod.start(now + 0.14)
      lockCarrier.stop(now + 0.9)
      lockMod.stop(now + 0.9)

      if (typeof navigator !== 'undefined' && navigator.vibrate) {
        navigator.vibrate([35, 25, 85])
      }
      }

      if (ctx.state === 'running') {
        trigger()
      } else {
        ctx.resume().then(trigger).catch(() => {})
      }
    } catch {}
  }

  // Efek suara Dark Tactical Solo Leveling "QUEST SKIPPED / DISMISSED" saat tombol Quest Skipped ditekan
  const playQuestSkipSound = () => {
    try {
      if (!prefSound || typeof window === 'undefined') return
      pendingArrivalSoundRef.current = false
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext
      if (!AudioCtx) return
      const ctx = audioCtxRef.current || new AudioCtx()
      audioCtxRef.current = ctx

      const trigger = () => {
        const now = ctx.currentTime + 0.005
        const master = ctx.createGain()
        master.gain.setValueAtTime(0.75, now)
        master.connect(ctx.destination)

        // 1. Short descending tactical power-down pulses (440 Hz -> 293.66 Hz)
        ;[440, 293.66].forEach((freq, idx) => {
          const t0 = now + idx * 0.055
          const osc = ctx.createOscillator()
          const flt = ctx.createBiquadFilter()
          const g = ctx.createGain()
          osc.type = 'sawtooth'
          osc.frequency.setValueAtTime(freq, t0)
          osc.frequency.exponentialRampToValueAtTime(freq * 0.78, t0 + 0.07)
          flt.type = 'lowpass'
          flt.frequency.setValueAtTime(1100, t0)
          flt.frequency.exponentialRampToValueAtTime(260, t0 + 0.08)
          g.gain.setValueAtTime(0.001, t0)
          g.gain.linearRampToValueAtTime(0.18, t0 + 0.008)
          g.gain.exponentialRampToValueAtTime(0.001, t0 + 0.09)
          osc.connect(flt)
          flt.connect(g)
          g.connect(master)
          osc.start(t0)
          osc.stop(t0 + 0.1)
        })

        // 2. Low obsidian shutter lock-off thud (95 Hz -> 38 Hz)
        const sub = ctx.createOscillator()
        const sg = ctx.createGain()
        sub.type = 'sine'
        sub.frequency.setValueAtTime(95, now + 0.02)
        sub.frequency.exponentialRampToValueAtTime(38, now + 0.24)
        sg.gain.setValueAtTime(0.001, now + 0.02)
        sg.gain.linearRampToValueAtTime(0.32, now + 0.045)
        sg.gain.exponentialRampToValueAtTime(0.001, now + 0.28)
        sub.connect(sg)
        sg.connect(master)
        sub.start(now + 0.02)
        sub.stop(now + 0.3)

        if (typeof navigator !== 'undefined' && navigator.vibrate) {
          navigator.vibrate([25, 20, 25])
        }
      }

      if (ctx.state === 'running') {
        trigger()
      } else {
        ctx.resume().then(trigger).catch(() => {})
      }
    } catch {}
  }

  const closeQuestAlertWithAnim = (afterClose?: () => void) => {
    if (isClosingQuestAlert) return
    pendingArrivalSoundRef.current = false
    setIsClosingQuestAlert(true)
    setTimeout(() => {
      setArrivedQuestAlert(null)
      setIsClosingQuestAlert(false)
      if (afterClose) afterClose()
    }, 260)
  }

  const playTimerBeep = () => {
    try {
      if (typeof window === 'undefined') return
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext
      if (!AudioCtx) return
      const ctx = new AudioCtx()
      const osc = ctx.createOscillator()
      const gain = ctx.createGain()
      osc.type = 'sine'
      osc.frequency.setValueAtTime(880, ctx.currentTime)
      gain.gain.setValueAtTime(0.25, ctx.currentTime)
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.8)
      osc.connect(gain)
      gain.connect(ctx.destination)
      osc.start()
      osc.stop(ctx.currentTime + 0.8)
    } catch (e) {
      console.error(e)
    }
  }

  const startRestCountdown = (seconds: number) => {
    requestNotificationPermission()
    const endTime = Date.now() + seconds * 1000
    restEndTimeRef.current = endTime
    setRestDurationPreset(seconds)
    setRestSecondsLeft(seconds)
    setRestTimerActive(true)
    setShowFloatingTimer(true)
    try {
      localStorage.setItem(
        'solo_rest_timer_target',
        JSON.stringify({ endTime, preset: seconds, active: true })
      )
    } catch (e) {
      console.error(e)
    }
  }

  const pauseRestCountdown = () => {
    if (restEndTimeRef.current) {
      const remaining = Math.max(0, Math.ceil((restEndTimeRef.current - Date.now()) / 1000))
      setRestSecondsLeft(remaining)
    }
    restEndTimeRef.current = null
    setRestTimerActive(false)
    try {
      localStorage.removeItem('solo_rest_timer_target')
    } catch (e) {
      console.error(e)
    }
  }

  const resumeRestCountdown = () => {
    const remaining = restSecondsLeft > 0 ? restSecondsLeft : (restDurationPreset || 60)
    startRestCountdown(remaining)
  }

  const extendRestCountdown = (extraSeconds: number) => {
    if (restTimerActive && restEndTimeRef.current) {
      restEndTimeRef.current += extraSeconds * 1000
      const remaining = Math.max(0, Math.ceil((restEndTimeRef.current - Date.now()) / 1000))
      setRestSecondsLeft(remaining)
      try {
        localStorage.setItem(
          'solo_rest_timer_target',
          JSON.stringify({ endTime: restEndTimeRef.current, preset: restDurationPreset, active: true })
        )
      } catch (e) {
        console.error(e)
      }
    } else {
      setRestSecondsLeft((s) => s + extraSeconds)
    }
  }

  const stopRestCountdown = (skipped: boolean = false) => {
    restEndTimeRef.current = null
    setRestTimerActive(false)
    setShowFloatingTimer(false)
    try {
      localStorage.removeItem('solo_rest_timer_target')
    } catch (e) {
      console.error(e)
    }
    if (skipped) {
      setRestSecondsLeft(restDurationPreset)
      showToast('Waktu istirahat dilewati. Siap latihan!')
    }
  }

  // Countdown timer istirahat berbasis Wall-Clock Timestamp
  // (Tetap berjalan akurat saat buka aplikasi lain, lock screen, atau minimize)
  useEffect(() => {
    if (!restTimerActive) return

    const tick = () => {
      if (!restEndTimeRef.current) return
      const now = Date.now()
      const remaining = Math.max(0, Math.ceil((restEndTimeRef.current - now) / 1000))

      if (remaining <= 0) {
        restEndTimeRef.current = null
        setRestSecondsLeft(0)
        setRestTimerActive(false)
        setShowFloatingTimer(false)
        try {
          localStorage.removeItem('solo_rest_timer_target')
        } catch (e) {}

        playTimerBeep()
        sendTimerNotification()
        if (typeof navigator !== 'undefined' && navigator.vibrate) {
          navigator.vibrate([300, 150, 300])
        }
        showToast('⚡ WAKTU ISTIRAHAT SELESAI! Siap untuk set berikutnya!')
      } else {
        setRestSecondsLeft(remaining)
      }
    }

    // Jalankan segera 1x saat aktif
    tick()

    // Interval 500ms agar update UI selalu presisi tanpa drift
    const interval = setInterval(tick, 500)

    // Handler ketika user beralih dari / kembali ke tab atau aplikasi lain
    const handleVisibilityChange = () => {
      if (document.visibilityState === 'visible') {
        tick()
      }
    }
    const handleWindowFocus = () => {
      tick()
    }

    document.addEventListener('visibilitychange', handleVisibilityChange)
    window.addEventListener('focus', handleWindowFocus)

    return () => {
      clearInterval(interval)
      document.removeEventListener('visibilitychange', handleVisibilityChange)
      window.removeEventListener('focus', handleWindowFocus)
    }
  }, [restTimerActive])

  const formatTimer = (totalSeconds: number) => {
    const mins = Math.floor(totalSeconds / 60)
    const secs = totalSeconds % 60
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`
  }

  const showToast = (msg: string) => {
    setStatusMessage(msg)
    setTimeout(() => setStatusMessage(null), 3200)
  }

  // Load persisted data from localStorage + check Supabase session
  useEffect(() => {
    setMounted(true)
    const savedFeaturedCat = localStorage.getItem('solo_featured_mastery_cat')
    if (savedFeaturedCat) setFeaturedCategoryName(savedFeaturedCat)
    const saved = localStorage.getItem('solo_community_v1')
    if (saved) {
      try {
        const parsed = JSON.parse(saved)
        if (parsed.users?.length) {
          // Normalisasi akun & sinkronisasi XP riwayat quest berdasarkan bobot kategori resmi
          const normalizedUsers = parsed.users.map((u: any) => {
            const userTasks = (parsed.personalTasks || []).filter(
              (t: any) => t.userId === u.id || (u.username && t.id.includes(u.username))
            )
            const userHistoryXp = userTasks.reduce((sum: number, t: any) => {
              const catXp = findCategory(t.category).xp
              const count = t.completedDates?.length || (t.done ? 1 : 0)
              return sum + count * catXp
            }, 0)
            const userDoneClanQuests = (parsed.clanQuests || []).filter((cq: any) => cq.completedByUserIds?.includes(u.id))
            const clanXp = userDoneClanQuests.reduce((sum: number, cq: any) => sum + findCategory(cq.category).xp, 0)
            const bonusDates = Array.isArray(u.dailyBonusDates) ? u.dailyBonusDates : []
            const bonusXp = bonusDates.length * DAILY_FULL_CLEAR_BONUS_XP
            const earnedXp = userHistoryXp + clanXp + bonusXp

            return { ...u, xp: earnedXp, dailyBonusDates: bonusDates }
          })
          setUsers(normalizedUsers)
        }
        if (parsed.currentUserId) setCurrentUserId(parsed.currentUserId)
        if (parsed.personalTasks) {
          const todayIso = getLocalIsoDate()
          const migrated = parsed.personalTasks.map((t: any) => {
            const cat = findCategory(t.category)
            let exs = t.workoutExercises
            if (exs && exs.length > 0 && exs[0]?.id === 'ex-1' && exs[0]?.name === 'Bench Press' && !t.done) {
              exs = []
            }
            const compDates = Array.isArray(t.completedDates) ? t.completedDates : []
            const skipDates = Array.isArray(t.skippedDates) ? t.skippedDates : []

            // SINKRONISASI RESET HARIAN (LOKAL WIB/LOCAL TIME):
            // Quest HANYA bernilai done/selesai HARI INI jika tanggal lokal hari ini (todayIso)
            // benar-benar ada di dalam completedDates!
            const isDoneToday = compDates.includes(todayIso)
            const isSkippedToday = skipDates.includes(todayIso)

            // Reset centang set gym sisa hari kemarin jika hari ini belum selesai
            const normalizedExs = Array.isArray(exs)
              ? isDoneToday
                ? exs
                : exs.map((ex: any) => ({
                    ...ex,
                    sets: Array.isArray(ex.sets)
                      ? ex.sets.map((s: any) => (s.completed ? { ...s, completed: false } : s))
                      : [],
                  }))
              : cat.name.toLowerCase() === 'gym'
                ? []
                : undefined

            return {
              ...t,
              category: cat.name,
              icon: cat.icon,
              xp: cat.xp,
              done: isDoneToday,
              skipped: isSkippedToday,
              completedDates: compDates,
              skippedDates: skipDates,
              workoutExercises: normalizedExs,
            }
          })
          setPersonalTasks(migrated)
        }
        if (parsed.clans?.length) setClans(parsed.clans)
        if (parsed.clanMembers) setClanMembers(parsed.clanMembers)
        if (parsed.clanQuests) {
          const migrated = parsed.clanQuests.map((cq: any) => {
            const cat = findCategory(cq.category)
            let exs = cq.workoutExercises
            if (exs && exs.length > 0 && exs[0]?.id === 'ex-1' && exs[0]?.name === 'Bench Press') {
              exs = []
            }
            return { ...cq, category: cat.name, icon: cat.icon, xp: cat.xp, workoutExercises: exs ?? (cat.name.toLowerCase() === 'gym' ? [] : undefined) }
          })
          setClanQuests(migrated)
        }
      } catch (e) {
        console.error(e)
      }
    }

    // Pulihkan timer istirahat jika sebelumnya sedang berjalan
    try {
      const savedTimer = localStorage.getItem('solo_rest_timer_target')
      if (savedTimer) {
        const parsedTimer = JSON.parse(savedTimer)
        if (parsedTimer && parsedTimer.active && parsedTimer.endTime) {
          const remaining = Math.max(0, Math.ceil((parsedTimer.endTime - Date.now()) / 1000))
          if (remaining > 0) {
            restEndTimeRef.current = parsedTimer.endTime
            setRestDurationPreset(parsedTimer.preset || 60)
            setRestSecondsLeft(remaining)
            setRestTimerActive(true)
            setShowFloatingTimer(true)
          } else {
            localStorage.removeItem('solo_rest_timer_target')
          }
        }
      }
    } catch (e) {
      console.error(e)
    }

    try {
      const savedPhotos = localStorage.getItem('solo_gym_photos_v1')
      if (savedPhotos) {
        const parsedPhotos = JSON.parse(savedPhotos)
        if (Array.isArray(parsedPhotos)) {
          setGymProgressPhotos(parsedPhotos)
        }
      }
    } catch (e) {
      console.error(e)
    }

    // Periksa cookie sesi login untuk memastikan akun sendiri yang aktif
    if (typeof document !== 'undefined') {
      const match = document.cookie.match(/(^| )hunter_session=([^;]+)/)
      const sessionUsername = match ? decodeURIComponent(match[2]) : null
      if (sessionUsername) {
        setUsers((prev) => {
          const found = prev.find(
            (u) =>
              u.username.toLowerCase() === sessionUsername.toLowerCase() ||
              u.email?.toLowerCase().includes(sessionUsername.toLowerCase())
          )
          if (found) {
            setCurrentUserId(found.id)
            return prev
          }
          const newUser: UserProfile = {
            id: `hunter-${sessionUsername.toLowerCase().replace(/[^a-z0-9]/g, '_')}`,
            username: sessionUsername,
            email: sessionUsername.includes('@') ? sessionUsername : `${sessionUsername.toLowerCase()}@gmail.com`,
            xp: 0,
            streak: 0,
          }
          setCurrentUserId(newUser.id)
          return [...prev, newUser]
        })
      }
    }

    if (isSupabaseConfigured && supabase) {
      supabase.auth.getSession().then(({ data }) => {
        if (data.session?.user) {
          const supaUser = data.session.user
          const uname = supaUser.user_metadata?.username || supaUser.email?.split('@')[0] || 'Hunter'
          setUsers((prev) => {
            if (prev.some((u) => u.id === supaUser.id)) return prev
            return [...prev, { id: supaUser.id, username: uname, email: supaUser.email || '', xp: 0, streak: 0 }]
          })
          setCurrentUserId(supaUser.id)
        }
      })
    }
  }, [])

  // Save state changes
  useEffect(() => {
    if (mounted) {
      localStorage.setItem(
        'solo_community_v1',
        JSON.stringify({
          users,
          currentUserId,
          personalTasks,
          clans,
          clanMembers,
          clanQuests,
        })
      )
    }
  }, [users, currentUserId, personalTasks, clans, clanMembers, clanQuests, mounted])

  // Derived Current User Data & Today / Upcoming Schedule Helpers
  const [timeTick, setTimeTick] = useState<number>(0)
  const lastLocalDateRef = useRef<string>(getLocalIsoDate())
  useEffect(() => {
    const refreshTick = () => {
      const nowIso = getLocalIsoDate()
      if (nowIso !== lastLocalDateRef.current) {
        lastLocalDateRef.current = nowIso
        setSelectedWeekDay(null)
        setShowCompletedDayQuests(false)
        setShowFinishedMyQuests(false)
      }
      setTimeTick(Date.now())
    }
    const timer = setInterval(refreshTick, 5000)
    const onVisibility = () => {
      if (document.visibilityState === 'visible') refreshTick()
    }
    window.addEventListener('focus', refreshTick)
    document.addEventListener('visibilitychange', onVisibility)
    return () => {
      clearInterval(timer)
      window.removeEventListener('focus', refreshTick)
      document.removeEventListener('visibilitychange', onVisibility)
    }
  }, [])

  const DAY_CODES = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'] as const
  const todayIsoStr = getLocalIsoDate()
  const todayDayCode = DAY_CODES[new Date().getDay()]
  const isQuestForToday = (schedule?: string[]) => {
    if (!schedule || schedule.length === 0) return true
    if (schedule.includes('Everyday')) return true
    return schedule.includes(todayDayCode)
  }

  const currentUser = users.find((u) => u.id === currentUserId) || users[0]
  const userPersonalTasks = personalTasks.filter(
    (t) =>
      t.userId === currentUser.id ||
      (currentUser.username && (t.userId === currentUser.username || t.id.includes(currentUser.username))) ||
      (!t.userId && currentUser.username === 'yongzz')
  )
  const sealedPersonalTasks = userPersonalTasks.filter((t) => Boolean(t.isSealed))
  const activeSchedulePersonalTasks = userPersonalTasks.filter((t) => !t.isSealed)
  const todayPersonalTasks = activeSchedulePersonalTasks.filter((t) => isQuestForToday(t.schedule))
  const upcomingPersonalTasks = activeSchedulePersonalTasks.filter((t) => !isQuestForToday(t.schedule))
  // Sumber kebenaran penyelesaian HARI INI adalah completedDates.includes(todayIsoStr), BUKAN boolean t.done yang bisa tertinggal dari kemarin
  const completedPersonalCount = userPersonalTasks.filter((t) => Boolean(t.completedDates?.includes(todayIsoStr))).length
  const completedTodayPersonalCount = todayPersonalTasks.filter((t) => Boolean(t.completedDates?.includes(todayIsoStr))).length
  const userJoinedMemberships = clanMembers.filter(
    (cm) => cm.userId === currentUser.id || (currentUser.username && cm.userId === currentUser.username)
  )
  const userJoinedClanIds = userJoinedMemberships.map((cm) => cm.clanId)
  const userJoinedClanQuests = clanQuests.filter((cq) => userJoinedClanIds.includes(cq.clanId))
  const completedClanQuestsCount = userJoinedClanQuests.filter(
    (cq) =>
      cq.completedByUserIds.includes(currentUser.id) ||
      (currentUser.username && cq.completedByUserIds.includes(currentUser.username))
  ).length
  const totalConsistencyTasks = userPersonalTasks.length + userJoinedClanQuests.length
  const totalCompletedConsistencyTasks = completedPersonalCount + completedClanQuestsCount
  const consistencyRate = totalConsistencyTasks > 0 ? Math.round((totalCompletedConsistencyTasks / totalConsistencyTasks) * 100) : 100

  // Derive History Quest Logs dari seluruh aktivitas latihan & penyelesaian quest user
  const userHistoryItems = (() => {
    const items: Array<{
      id: string
      questId: string
      title: string
      category: string
      icon: string
      xp: number
      isoDate: string
      dateLabel: string
      fullDateLabel: string
      timestamp: number
      isGym: boolean
      exercises: Array<{ name: string; setsCount: number; weight: number; reps: number }>
      totalSets: number
      maxWeight: number
    }> = []

    const todayIso = getLocalIsoDate()
    const yesterdayDate = new Date()
    yesterdayDate.setDate(yesterdayDate.getDate() - 1)
    const yesterdayIso = getLocalIsoDate(yesterdayDate)
    const todayShort = new Date().toLocaleDateString('id-ID', { day: '2-digit', month: 'short' })
    const DAYS_ID = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu']

    const formatFullDateId = (isoStr: string) => {
      const parsed = new Date(`${isoStr}T00:00:00`)
      if (isNaN(parsed.getTime())) return isoStr
      const dayName = DAYS_ID[parsed.getDay()]
      const dmy = parsed.toLocaleDateString('id-ID', {
        day: '2-digit',
        month: 'short',
        year: 'numeric',
      })
      if (isoStr === todayIso) return `Hari Ini • ${dayName}, ${dmy}`
      if (isoStr === yesterdayIso) return `Kemarin • ${dayName}, ${dmy}`
      return `${dayName}, ${dmy}`
    }

    userPersonalTasks.forEach((task) => {
      // HANYA QUEST YANG BENAR-BENAR MEMILIKI TANGGAL SELESAI DI completedDates YANG MASUK KE HISTORY
      const completionDates: string[] = Array.from(new Set(task.completedDates || []))
      if (completionDates.length === 0) return

      const isGym = task.category.toLowerCase() === 'gym' || Boolean(task.workoutExercises && task.workoutExercises.length > 0)

      completionDates.forEach((isoDate) => {
        const parsed = new Date(`${isoDate}T00:00:00`)
        const dateLabel = !isNaN(parsed.getTime())
          ? parsed.toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' })
          : todayShort
        const shortHistLookup = !isNaN(parsed.getTime())
          ? parsed.toLocaleDateString('id-ID', { day: '2-digit', month: 'short' })
          : todayShort
        const fullDateLabel = formatFullDateId(isoDate)
        const timestamp = !isNaN(parsed.getTime()) ? parsed.getTime() : Date.now()

        if (isGym && task.workoutExercises && task.workoutExercises.length > 0) {
          const exercises = task.workoutExercises.map((ex) => {
            const histOnDate = ex.history?.find((h) => h.date === shortHistLookup || h.date === dateLabel)
            const weights = ex.sets.map((s) => Number(s.weight) || 0)
            const maxW = histOnDate ? histOnDate.weight : weights.length > 0 ? Math.max(...weights) : 0
            const reps = (histOnDate && histOnDate.reps !== undefined) ? histOnDate.reps : (Number(ex.sets[0]?.reps) || 10)
            return {
              name: ex.name,
              setsCount: ex.sets.length,
              weight: maxW,
              reps,
            }
          })

          const totalSets = exercises.reduce((acc, e) => acc + e.setsCount, 0)
          const maxWeight = exercises.reduce((acc, e) => Math.max(acc, Number(e.weight) || 0), 0)

          items.push({
            id: `${task.id}-${isoDate}`,
            questId: task.id,
            title: task.title,
            category: task.category,
            icon: task.icon,
            xp: task.xp,
            isoDate,
            dateLabel,
            fullDateLabel,
            timestamp,
            isGym: true,
            exercises,
            totalSets,
            maxWeight,
          })
        } else {
          items.push({
            id: `${task.id}-${isoDate}`,
            questId: task.id,
            title: task.title,
            category: task.category,
            icon: task.icon,
            xp: task.xp,
            isoDate,
            dateLabel,
            fullDateLabel,
            timestamp,
            isGym: false,
            exercises: [],
            totalSets: 0,
            maxWeight: 0,
          })
        }
      })
    })

    return items.sort((a, b) => b.timestamp - a.timestamp)
  })()

  const totalHistorySets = userHistoryItems.reduce((acc, item) => acc + item.totalSets, 0)
  const maxHistoryWeight = userHistoryItems.reduce((acc, item) => Math.max(acc, item.maxWeight), 0)

  // Derive Akumulasi XP Valid dari Riwayat Quest, Daily All-Clear Bonus & Clan Challenge
  const historyTotalXp = userHistoryItems.reduce((acc, item) => acc + findCategory(item.category).xp, 0)
  const clanCompletedQuestsList = userJoinedClanQuests.filter(
    (cq) =>
      cq.completedByUserIds.includes(currentUser.id) ||
      (currentUser.username && cq.completedByUserIds.includes(currentUser.username))
  )
  const clanCompletedTotalXp = clanCompletedQuestsList.reduce((acc, cq) => acc + findCategory(cq.category).xp, 0)
  const isDailyAllClearEligible = todayPersonalTasks.length >= MIN_QUESTS_FOR_DAILY_BONUS
  const isDailyAllClearToday =
    isDailyAllClearEligible &&
    todayPersonalTasks.every((t) => Boolean(t.completedDates?.includes(todayIsoStr)))
  const userDailyBonusDates = Array.isArray(currentUser.dailyBonusDates) ? currentUser.dailyBonusDates : []
  const effectiveDailyBonusDates = isDailyAllClearToday
    ? Array.from(new Set([...userDailyBonusDates, todayIsoStr]))
    : userDailyBonusDates.filter((d) => d !== todayIsoStr)
  const dailyBonusTotalXp = effectiveDailyBonusDates.length * DAILY_FULL_CLEAR_BONUS_XP

  const effectiveXp = historyTotalXp + dailyBonusTotalXp + clanCompletedTotalXp

  const levelInfo = getHunterLevelInfo(effectiveXp)
  const currentLevel = levelInfo.level
  const currentRank = getHunterRank(effectiveXp)
  const currentRankTier = HUNTER_RANK_TIERS.find((t) => t.rank === currentRank) || HUNTER_RANK_TIERS[0]
  const nextLevelXp = levelInfo.nextLevelTotalXp
  const levelProgress = levelInfo.progressPct

  // Derive Category Mastery (XP & Rank E-S per Kategori)
  // Aturan: Kategori yang memiliki minimal 1 quest (aktif terdaftar atau riwayat selesai) = TERBUKA (Unlocked)
  // Kategori lainnya = TERKUNCI (Locked). Untuk unlock, buat minimal 1 quest pada kategori tersebut.
  const categoryMasteries = CATEGORIES.map((cat) => {
    const matchingPersonal = userHistoryItems.filter((item) => findCategory(item.category).name === cat.name)
    const matchingClan = clanCompletedQuestsList.filter(
      (cq) => userJoinedClanIds.includes(cq.clanId) && findCategory(cq.category).name === cat.name
    )
    const personalTasksInCat = userPersonalTasks.filter((t) => findCategory(t.category).name === cat.name)
    const clanTasksInCat = userJoinedClanQuests.filter((cq) => findCategory(cq.category).name === cat.name)
    const totalQuestCount = personalTasksInCat.length + clanTasksInCat.length
    const count = matchingPersonal.length + matchingClan.length
    const catXp = matchingPersonal.length * cat.xp + matchingClan.length * cat.xp
    const rankInfo = getCategoryRankInfo(catXp)
    const hasQuest = totalQuestCount > 0 || count > 0 || catXp > 0
    return {
      name: cat.name,
      icon: cat.icon,
      xpPerQuest: cat.xp,
      xp: catXp,
      count,
      totalQuestCount,
      hasQuest,
      ...rankInfo,
    }
  })
  // Kategori yang memiliki quest (Terbuka / Aktif)
  const unlockedMasteries = categoryMasteries.filter((m) => m.hasQuest)
  // Kategori yang belum memiliki quest (Terkunci - butuh minimal 1 quest untuk unlock)
  const lockedMasteries = categoryMasteries.filter((m) => !m.hasQuest)
  const activeMasteries = unlockedMasteries
  const sRankCategories = unlockedMasteries.filter((m) => m.rank === 'S')
  const topMasteryCategories = [...unlockedMasteries]
    .sort((a, b) => b.xp - a.xp || b.count - a.count || b.totalQuestCount - a.totalQuestCount)
  const featuredCategory = (() => {
    if (featuredCategoryName) {
      const found = unlockedMasteries.find((c) => c.name === featuredCategoryName)
      if (found) return found
    }
    return topMasteryCategories[0] || null
  })()

  // Derive Personal Records (PR) & Total Volume dari semua gerakan latihan
  const userExerciseRecords = (() => {
    const records: Array<{
      questId: string
      questTitle: string
      exerciseId: string
      name: string
      maxWeight: number
      bestReps: number
      setsCount: number
      volume: number
    }> = []

    userPersonalTasks.forEach((task) => {
      if (!task.workoutExercises) return
      task.workoutExercises.forEach((ex) => {
        const setWeights = ex.sets.map((s) => Number(s.weight) || 0)
        const histWeights = (ex.history || []).map((h) => Number(h.weight) || 0)
        const maxWeight = Math.max(0, ...setWeights, ...histWeights)
        const bestSet = ex.sets.find((s) => (Number(s.weight) || 0) === maxWeight) || ex.sets[0]
        const bestReps = Number(bestSet?.reps) || 10
        const sessionVolume = ex.sets.reduce(
          (sum, s) => sum + (Number(s.weight) || 0) * (Number(s.reps) || 0),
          0
        )
        const sessionsCount = Math.max(1, ex.history?.length || 1)
        records.push({
          questId: task.id,
          questTitle: task.title,
          exerciseId: ex.id,
          name: ex.name,
          maxWeight,
          bestReps,
          setsCount: ex.sets.length,
          volume: sessionVolume * sessionsCount,
        })
      })
    })

    return records.sort((a, b) => b.maxWeight - a.maxWeight)
  })()

  const totalLiftedVolume = userExerciseRecords.reduce((acc, r) => acc + r.volume, 0)
  const topPrRecord = userExerciseRecords[0] || null

  // Derive 7-Day Weekly Schedule & Activity Strip (Sen - Min)
  const currentWeekDays = (() => {
    const now = new Date()
    const currentDayIdx = now.getDay() // 0 = Sun, 1 = Mon, ...
    const diffToMonday = currentDayIdx === 0 ? -6 : 1 - currentDayIdx
    const monday = new Date(now.getFullYear(), now.getMonth(), now.getDate() + diffToMonday)
    const todayIso = getLocalIsoDate(now)

    const order: Array<{ code: string; shortLabel: string; fullName: string }> = [
      { code: 'Mon', shortLabel: 'Sen', fullName: 'Senin' },
      { code: 'Tue', shortLabel: 'Sel', fullName: 'Selasa' },
      { code: 'Wed', shortLabel: 'Rab', fullName: 'Rabu' },
      { code: 'Thu', shortLabel: 'Kam', fullName: 'Kamis' },
      { code: 'Fri', shortLabel: 'Jum', fullName: 'Jumat' },
      { code: 'Sat', shortLabel: 'Sab', fullName: 'Sabtu' },
      { code: 'Sun', shortLabel: 'Min', fullName: 'Minggu' },
    ]

    return order.map((item, idx) => {
      const d = new Date(monday.getFullYear(), monday.getMonth(), monday.getDate() + idx)
      const isoDate = getLocalIsoDate(d)
      const dateNum = String(d.getDate()).padStart(2, '0')
      const isToday = isoDate === todayIso
      const isPast = isoDate < todayIso
      const isFuture = isoDate > todayIso

      const scheduledTasks = userPersonalTasks.filter((t) => {
        if (t.isSealed) return false
        if (!t.schedule || t.schedule.length === 0 || t.schedule.includes('Everyday')) return true
        return t.schedule.includes(item.code)
      })

      const isDone = userPersonalTasks.some((t) => Boolean(t.completedDates?.includes(isoDate)))

      return {
        ...item,
        dateNum,
        isoDate,
        isToday,
        isPast,
        isFuture,
        scheduledTasks,
        isDone,
      }
    })
  })()

  const activeScheduleDayCode =
    selectedWeekDay ||
    (todayPersonalTasks.length > 0
      ? todayDayCode
      : currentWeekDays.find((d) => d.scheduledTasks.length > 0)?.code || todayDayCode)
  const activeScheduleDayObj =
    currentWeekDays.find((d) => d.code === activeScheduleDayCode) || currentWeekDays[0]

  // Sinkronisasi otomatis dengan Supabase Cloud (Quest & Progres Beban)
  const syncWithCloud = async (forcePushLocal = false) => {
    if (!currentUser || !isSupabaseConfigured) return
    setCloudSyncStatus('syncing')
    try {
      const [cloudQuests, cloudProfile, cloudVault] = await Promise.all([
        fetchCloudQuests(currentUser.id, currentUser.username),
        fetchCloudProfile(currentUser.id, currentUser.username),
        fetchCloudFinanceVault(currentUser.id),
      ])

      // Sinkronisasi Finance Vault Cloud <-> Local
      try {
        const userKey = `solo_finance_vault_v1_${currentUser.id}`
        const localRaw = typeof window !== 'undefined' ? localStorage.getItem(userKey) : null
        const localVault: FinanceVaultState | null = localRaw ? JSON.parse(localRaw) : null
        if (cloudVault && (!localVault || (cloudVault.updatedAt || 0) >= (localVault.updatedAt || 0))) {
          setFinanceVault(cloudVault)
          setMonthlyIncomeDraft(String(cloudVault.monthlyIncome))
          if (typeof window !== 'undefined') {
            localStorage.setItem(userKey, JSON.stringify(cloudVault))
          }
        } else if (localVault && (localVault.updatedAt || 0) > (cloudVault?.updatedAt || 0)) {
          saveCloudFinanceVault(currentUser.id, currentUser.username, localVault)
        }
      } catch (vaultSyncErr) {
        console.warn('Finance Vault sync notice:', vaultSyncErr)
      }

      if (cloudProfile) {
        setUsers((prev) =>
          prev.map((u) =>
            u.id === currentUser.id || (currentUser.username && u.username === currentUser.username)
              ? {
                  ...u,
                  ...cloudProfile,
                  xp: Math.max(u.xp || 0, cloudProfile.xp || 0, effectiveXp),
                  streak: Math.max(u.streak || 0, cloudProfile.streak || 0),
                }
              : u
          )
        )
      } else if (currentUser) {
        saveCloudProfile({ ...currentUser, xp: effectiveXp })
      }

      if (cloudQuests && cloudQuests.length > 0 && !forcePushLocal) {
        const todayIso = getLocalIsoDate()
        const normalizedCloudQuests = cloudQuests.map((t: any) => {
          const cat = findCategory(t.category)
          const existingLocal = personalTasks.find((lt) => lt.id === t.id)
          const skipDates = Array.from(
            new Set([
              ...(Array.isArray(t.skippedDates) ? t.skippedDates : []),
              ...(existingLocal?.skippedDates || []),
            ])
          )
          const compSet = new Set<string>([
            ...(Array.isArray(t.completedDates) ? t.completedDates : []),
            ...(existingLocal?.completedDates || []),
          ])
          const exList: WorkoutExercise[] = Array.isArray(t.workoutExercises) ? t.workoutExercises : []
          const compDates = Array.from(compSet)
          const isDoneToday = compDates.includes(todayIso)
          // Jika quest belum selesai hari ini, reset centang set sisa dari sesi hari sebelumnya
          const cleanedExercises = isDoneToday
            ? exList
            : exList.map((ex) => ({
                ...ex,
                sets: Array.isArray(ex.sets)
                  ? ex.sets.map((s) => (s.completed ? { ...s, completed: false } : s))
                  : [],
              }))
          return {
            ...t,
            category: cat.name,
            icon: cat.icon,
            xp: cat.xp,
            done: isDoneToday,
            skipped: skipDates.includes(todayIso),
            completedDates: compDates,
            skippedDates: skipDates,
            workoutExercises: cleanedExercises,
          }
        })
        setPersonalTasks((prev) => {
          const otherTasks = prev.filter(
            (t) => t.userId !== currentUser.id && (!currentUser.username || !t.id.includes(currentUser.username))
          )
          return [...otherTasks, ...normalizedCloudQuests]
        })
        setCloudSyncStatus('synced')
      } else {
        const localTasks = personalTasks.filter((t) => t.userId === currentUser.id)
        if (localTasks.length > 0) {
          await saveAllCloudQuests(localTasks, currentUser.username)
        }
        setCloudSyncStatus('synced')
      }
    } catch (e) {
      console.warn('Supabase sync notice:', e)
      setCloudSyncStatus('offline')
    }
  }

  useEffect(() => {
    if (mounted && currentUser) {
      syncWithCloud()
    }
  }, [mounted, currentUser?.id, currentUser?.username])

  // Save Gym progress photos to localStorage
  useEffect(() => {
    if (!mounted) return
    try {
      localStorage.setItem('solo_gym_photos_v1', JSON.stringify(gymProgressPhotos))
    } catch (e) {
      console.error(e)
    }
  }, [gymProgressPhotos, mounted])

  // Load Finance Vault per-user from localStorage
  useEffect(() => {
    if (!mounted || !currentUser?.id) return
    try {
      const userKey = `solo_finance_vault_v1_${currentUser.id}`
      const savedVault = localStorage.getItem(userKey) || localStorage.getItem('solo_finance_vault_v1')
      if (savedVault) {
        const parsed = JSON.parse(savedVault)
        if (parsed && typeof parsed === 'object') {
          const normalized: FinanceVaultState = {
            monthlyIncome: typeof parsed.monthlyIncome === 'number' ? parsed.monthlyIncome : DEFAULT_FINANCE_VAULT.monthlyIncome,
            buckets: Array.isArray(parsed.buckets) && parsed.buckets.length > 0 ? parsed.buckets : DEFAULT_FINANCE_VAULT.buckets,
            goals: Array.isArray(parsed.goals) ? parsed.goals : DEFAULT_FINANCE_VAULT.goals,
            logs: Array.isArray(parsed.logs) ? parsed.logs : [],
            updatedAt: typeof parsed.updatedAt === 'number' ? parsed.updatedAt : 0,
          }
          setFinanceVault(normalized)
          setMonthlyIncomeDraft(String(normalized.monthlyIncome))
          if (normalized.buckets[0]) setFinanceSelectedBucketId(normalized.buckets[0].id)
          if (normalized.goals[0]) setFinanceSelectedGoalId(normalized.goals[0].id)
          return
        }
      }
      setFinanceVault(DEFAULT_FINANCE_VAULT)
      setMonthlyIncomeDraft(String(DEFAULT_FINANCE_VAULT.monthlyIncome))
    } catch (e) {
      console.error(e)
    }
  }, [mounted, currentUser?.id])

  // Lenis smooth inertial scrolling + real-time 60fps scroll-linked morph header & 3D card uncurl
  useEffect(() => {
    if (typeof window === 'undefined') return
    const lenis = new Lenis({
      duration: 1.05,
      lerp: 0.11,
      smoothWheel: true,
    })
    lenisRef.current = lenis

    let rafId = 0
    let smoothScroll = window.scrollY || 0
    let currentTiltX = 0
    let currentTiltY = 0
    const cardLerp: Record<number, number> = {}

    const raf = (time: number) => {
      lenis.raf(time)

      const rawScroll = Math.max(0, lenis.animatedScroll ?? window.scrollY ?? 0)
      smoothScroll += (rawScroll - smoothScroll) * 0.25
      const maxScroll = Math.max(0, document.documentElement.scrollHeight - window.innerHeight)
      const scrollRatio = maxScroll > 0 ? Math.min(1, Math.max(0, smoothScroll / maxScroll)) : 0

      // 1. Sticky Morphing Header (#header-normal <-> #header-minihud + #scroll-laser)
      const pctEl = document.getElementById('header-scroll-pct')
      if (pctEl) pctEl.textContent = `${Math.round(scrollRatio * 100)}%`

      const laserEl = document.getElementById('scroll-laser')
      if (laserEl) laserEl.style.width = `${(scrollRatio * 100).toFixed(1)}%`

      const morphT = Math.min(1, Math.max(0, (smoothScroll - 22) / 40))
      const hNormal = document.getElementById('header-normal')
      const hMini = document.getElementById('header-minihud')
      if (hNormal && hMini) {
        hNormal.style.opacity = (1 - morphT).toFixed(3)
        hNormal.style.transform = `translate3d(0, ${(-morphT * 10).toFixed(1)}px, 0)`
        hNormal.style.pointerEvents = morphT > 0.5 ? 'none' : 'auto'

        hMini.style.opacity = morphT.toFixed(3)
        hMini.style.transform = `translate3d(0, ${((1 - morphT) * -10).toFixed(1)}px, 0)`
        hMini.style.pointerEvents = morphT > 0.5 ? 'auto' : 'none'
      }

      // 2. Hero #hero-card 3D Scroll Parallax + Cursor Tilt
      const heroEl = document.getElementById('hero-card')
      if (heroEl) {
        const heroT = Math.min(1, smoothScroll / 160)
        const hScale = 1 - heroT * 0.085
        const hRotX = heroT * 10
        const hOpacity = Math.max(0.42, 1 - heroT * 0.52)
        currentTiltX += (heroTiltTargetRef.current.x - currentTiltX) * 0.16
        currentTiltY += (heroTiltTargetRef.current.y - currentTiltY) * 0.16

        heroEl.style.transform = `perspective(700px) scale(${hScale.toFixed(4)}) rotateX(${(hRotX + currentTiltX).toFixed(2)}deg) rotateY(${currentTiltY.toFixed(2)}deg) translate3d(0, ${(heroT * 10).toFixed(1)}px, 0)`
        heroEl.style.opacity = hOpacity.toFixed(3)
      }

      // 3. Scroll-Linked 3D Card Uncurl for [data-scroll-card] sections
      const vpH = window.innerHeight || 720
      const scrollCards = document.querySelectorAll<HTMLElement>('[data-scroll-card]')
      scrollCards.forEach((card, idx) => {
        const rect = card.getBoundingClientRect()
        const inView = rect.top < vpH - 20 && rect.bottom > 24
        const bottomVis = Math.min(1, Math.max(0, (vpH - rect.top) / 140))
        const topVis = Math.min(1, Math.max(0, (rect.bottom - 54) / 120))
        const target = inView ? Math.min(1, 0.22 + 0.78 * Math.min(bottomVis, topVis)) : 0.18
        const prev = cardLerp[idx] !== undefined ? cardLerp[idx] : (inView ? 1 : 0.18)
        const next = prev + (target - prev) * 0.16
        cardLerp[idx] = next

        const yOff = (1 - next) * 24
        const sc = 0.94 + next * 0.06
        const rx = (1 - next) * 7
        card.style.transform = `perspective(650px) translate3d(0, ${yOff.toFixed(1)}px, 0) scale(${sc.toFixed(4)}) rotateX(${rx.toFixed(2)}deg)`
        card.style.opacity = Math.min(1, next + 0.08).toFixed(3)
      })

      rafId = requestAnimationFrame(raf)
    }

    rafId = requestAnimationFrame(raf)
    return () => {
      cancelAnimationFrame(rafId)
      lenisRef.current = null
      lenis.destroy()
    }
  }, [])

  // Pause Lenis & lock background scroll when Top Transaction Drawer / Sheet / Nav Menu / Finance FAB / Settings Modal is open
  useEffect(() => {
    const shouldLock = Boolean(activeFinanceSheet || isNavAddMenuOpen || isFinanceFabOpen || isPreferencesModalOpen)
    if (shouldLock) {
      lenisRef.current?.stop()
      document.documentElement.style.overflow = 'hidden'
      document.body.style.overflow = 'hidden'
    } else {
      lenisRef.current?.start()
      document.documentElement.style.overflow = ''
      document.body.style.overflow = ''
    }
    return () => {
      lenisRef.current?.start()
      document.documentElement.style.overflow = ''
      document.body.style.overflow = ''
    }
  }, [activeFinanceSheet, isNavAddMenuOpen, isFinanceFabOpen, isPreferencesModalOpen])

  // Cleanup live flip interval & camera stream on unmount or leave photos subpage
  useEffect(() => {
    if (workoutSubPage !== 'photos') {
      if (liveFlipTimerRef.current) {
        clearInterval(liveFlipTimerRef.current)
        liveFlipTimerRef.current = null
      }
      if (cameraStreamRef.current) {
        cameraStreamRef.current.getTracks().forEach((t) => t.stop())
        cameraStreamRef.current = null
      }
      setIsCameraOpen(false)
      setIsPlayingTimelapse(false)
      setLiveFlipIdx(null)
    }
  }, [workoutSubPage])

  // Attach active camera stream to <video> element when camera modal opens
  useEffect(() => {
    if (isCameraOpen && cameraVideoRef.current && cameraStreamRef.current) {
      cameraVideoRef.current.srcObject = cameraStreamRef.current
      cameraVideoRef.current.play().catch(() => {})
    }
  }, [isCameraOpen, cameraFacingMode])

  // Reset harian otomatis ketika berganti hari / tengah malam (midnight rollover):
  // Jika quest belum selesai pada hari ini (!compSet.has(todayIso)) dan tidak sedang dibuka di sesi workout aktif,
  // pastikan seluruh set gerakan latihan (s.completed) direset kembali ke false agar sesi hari berikutnya mulai dari 0.
  useEffect(() => {
    if (!mounted) return
    const todayIso = getLocalIsoDate()
    setPersonalTasks((prev) => {
      let changed = false
      const updated = prev.map((t) => {
        const compDates = Array.isArray(t.completedDates) ? t.completedDates : []
        const skipDates = Array.isArray(t.skippedDates) ? t.skippedDates : []
        const isDoneToday = compDates.includes(todayIso)
        const isSkippedToday = skipDates.includes(todayIso)
        const isCurrentlyActiveWorkout = activeWorkoutQuest?.id === t.id && !activeWorkoutQuest?.viewOnly

        const hasStaleCompletedSets =
          !isDoneToday &&
          !isCurrentlyActiveWorkout &&
          Boolean(t.workoutExercises?.some((ex) => ex.sets.some((s) => s.completed)))

        if (t.done !== isDoneToday || t.skipped !== isSkippedToday || hasStaleCompletedSets) {
          changed = true
          const nextExercises = hasStaleCompletedSets
            ? (t.workoutExercises || []).map((ex) => ({
                ...ex,
                sets: ex.sets.map((s) => (s.completed ? { ...s, completed: false } : s)),
              }))
            : t.workoutExercises

          const updatedTask: PersonalTask = {
            ...t,
            done: isDoneToday,
            skipped: isSkippedToday,
            workoutExercises: nextExercises,
          }
          if (hasStaleCompletedSets && currentUser) {
            saveCloudQuest(updatedTask, currentUser.username)
          }
          return updatedTask
        }
        return t
      })
      return changed ? updated : prev
    })
  }, [timeTick, mounted, activeWorkoutQuest?.id, activeWorkoutQuest?.viewOnly])

  const markQuestAlertHandled = (task: PersonalTask) => {
    if (!task.targetTime || task.id === 'preview-quest') return
    try {
      const todayIso = getLocalIsoDate()
      const raw = localStorage.getItem('solo_quest_handled_v2')
      const parsed = raw ? JSON.parse(raw) : []
      const keys: string[] = Array.isArray(parsed)
        ? parsed.filter((k) => typeof k === 'string' && k.startsWith(`${todayIso}:`))
        : []
      const handledSet = new Set(keys)
      handledSet.add(`${todayIso}:${task.id}:${task.targetTime}`)
      localStorage.setItem('solo_quest_handled_v2', JSON.stringify(Array.from(handledSet)))
    } catch {}
  }

  // Deteksi otomatis saat Quest ber-jam sudah memasuki / melewati jamnya (tanpa batas durasi) ->
  // Hanya aktif saat layar/tab sedang terlihat (visible) agar tidak terlewat di background.
  // Status "handled" HANYA disimpan saat user benar-benar menekan TERIMA QUEST atau QUEST SKIPPED.
  // Jika ada beberapa quest terlewat (mis. 2 quest), antrekan agar pop-up muncul berurutan satu per satu!
  useEffect(() => {
    if (!mounted || arrivedQuestAlert) return
    if (typeof document !== 'undefined' && document.visibilityState !== 'visible') return
    const todayIso = getLocalIsoDate()
    let handledKeys: string[] = []
    try {
      const raw = localStorage.getItem('solo_quest_handled_v2')
      const parsed = raw ? JSON.parse(raw) : []
      if (Array.isArray(parsed)) {
        // Hanya simpan kunci hari ini agar storage tetap ringan
        handledKeys = parsed.filter((k) => typeof k === 'string' && k.startsWith(`${todayIso}:`))
      }
    } catch {}
    const handledSet = new Set(handledKeys)

    const pendingArrived = todayPersonalTasks
      .filter((t) => {
        if (!t.targetTime) return false
        if (t.completedDates?.includes(todayIso)) return false
        if (t.skippedDates?.includes(todayIso)) return false
        if (!isQuestTimeArrived(t.targetTime, t.schedule)) return false
        const key = `${todayIso}:${t.id}:${t.targetTime}`
        return !handledSet.has(key)
      })
      .sort((a, b) => (parseTargetTimeMinutes(a.targetTime) ?? 0) - (parseTargetTimeMinutes(b.targetTime) ?? 0))

    if (pendingArrived.length > 0) {
      const newlyArrived = pendingArrived[0]
      setPendingQuestAlertCount(pendingArrived.length)
      if (hasUserInteractedRef.current) {
        setIsQuestAlertSealed(false)
        setQuestAlertAnimKey((k) => k + 1)
        setArrivedQuestAlert(newlyArrived)
        playQuestArrivalSound()
      } else {
        // Cold launch PWA sebelum ada sentuhan pertama: tampilkan segel hologram tertutup
        // agar saat user mengetuk, shutter terbuka (Smart Animate) & suara System HUD berbunyi sinkron!
        setIsQuestAlertSealed(true)
        setArrivedQuestAlert(newlyArrived)
      }
      // Tidak memanggil `new Notification(...)` di sini karena effect ini hanya berjalan
      // saat user sudah berada di dalam app (`visibilityState === 'visible'`) sehingga
      // pop-up System HUD in-app sudah tampil dan tidak menimbulkan notifikasi OS ganda
      // setiap kali user masuk ke app sebelum quest diterima.
    } else {
      setPendingQuestAlertCount(0)
    }
  }, [timeTick, mounted, todayPersonalTasks, arrivedQuestAlert, prefNotification, prefSound])

  const getPushEnvironmentInfo = (): 'ready' | 'needs-pwa' | 'unsupported' => {
    if (typeof window === 'undefined') return 'unsupported'
    const ua = window.navigator.userAgent || ''
    const isIos = /iPad|iPhone|iPod/.test(ua) || (window.navigator.platform === 'MacIntel' && window.navigator.maxTouchPoints > 1)
    const isStandalone =
      window.matchMedia?.('(display-mode: standalone)')?.matches || Boolean((window.navigator as any).standalone)
    if (isIos && !isStandalone) {
      return 'needs-pwa'
    }
    if (!('serviceWorker' in navigator) || !('PushManager' in window) || !('Notification' in window)) {
      return 'unsupported'
    }
    return 'ready'
  }

  const syncSubscriptionToServer = async (subscription: PushSubscription) => {
    if (!currentUser?.id) return false
    const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone || 'Asia/Jakarta'
    const res = await fetch('/api/push/subscribe', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        userId: currentUser.id,
        username: currentUser.username,
        timezone,
        subscription: subscription.toJSON(),
      }),
    })
    return res.ok
  }

  useEffect(() => {
    if (!mounted || !currentUser?.id) return
    let cancelled = false
    const initServiceWorkerAndPush = async () => {
      const env = getPushEnvironmentInfo()
      if (env !== 'ready') {
        if (!cancelled) {
          setPushStatus(env)
          setPushStatusNote(
            env === 'needs-pwa'
              ? 'Di iPhone/iPad: tekan Share -> Add to Home Screen dulu, lalu buka app dari layar utama.'
              : 'Browser ini belum mendukung Web Push Latar Belakang.'
          )
        }
        return
      }
      try {
        const reg = await navigator.serviceWorker.register('/sw.js', { scope: '/' })
        await navigator.serviceWorker.ready
        if (cancelled) return
        swRegistrationRef.current = reg
        const existingSub = await reg.pushManager.getSubscription()
        if (existingSub && Notification.permission === 'granted') {
          setPushStatus('active')
          setPushStatusNote('')
          await syncSubscriptionToServer(existingSub)
        } else if (Notification.permission === 'denied') {
          setPushStatus('denied')
          setPushStatusNote('Izin notifikasi diblokir. Aktifkan lagi di Pengaturan situs browser/HP.')
        } else {
          setPushStatus('prompt')
          setPushStatusNote('')
        }
      } catch (err: any) {
        if (!cancelled) {
          setPushStatus('prompt')
          setPushStatusNote(err?.message || '')
        }
      }
    }
    void initServiceWorkerAndPush()
    return () => {
      cancelled = true
    }
  }, [mounted, currentUser?.id, currentUser?.username])

  const enableBackgroundPush = async (silent = false): Promise<boolean> => {
    const env = getPushEnvironmentInfo()
    if (env === 'needs-pwa') {
      setPushStatus('needs-pwa')
      if (!silent) {
        showToast('Di iPhone/iPad: install app via Share -> Add to Home Screen dulu agar notifikasi background bisa aktif.')
      }
      return false
    }
    if (env === 'unsupported') {
      setPushStatus('unsupported')
      if (!silent) {
        showToast('Perangkat atau browser ini belum mendukung notifikasi latar belakang.')
      }
      return false
    }
    const vapidPublicKey = process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY
    if (!vapidPublicKey) {
      if (!silent) showToast('VAPID key belum terkonfigurasi di server.')
      return false
    }
    setIsSubscribingPush(true)
    try {
      let perm: NotificationPermission = Notification.permission
      if (perm === 'default') {
        perm = await Notification.requestPermission()
      }
      if (perm !== 'granted') {
        setPushStatus('denied')
        setPushStatusNote('Izin notifikasi ditolak atau diblokir oleh browser.')
        if (!silent) {
          showToast('Izin notifikasi ditolak. Aktifkan izin notifikasi di pengaturan browser/perangkat.')
        }
        return false
      }
      const reg = swRegistrationRef.current || (await navigator.serviceWorker.register('/sw.js', { scope: '/' }))
      await navigator.serviceWorker.ready
      swRegistrationRef.current = reg

      let sub = await reg.pushManager.getSubscription()
      if (!sub) {
        sub = await reg.pushManager.subscribe({
          userVisibleOnly: true,
          applicationServerKey: urlBase64ToUint8Array(vapidPublicKey),
        })
      }
      const synced = await syncSubscriptionToServer(sub)
      if (!synced) {
        if (!silent) showToast('Gagal menyimpan langganan push ke server cloud.')
        return false
      }
      setPushStatus('active')
      setPushStatusNote('')
      setPrefNotification(true)
      if (!silent) {
        showToast('Notifikasi latar belakang aktif! Quest terjadwal akan berbunyi meski app ditutup.')
      }
      return true
    } catch (err: any) {
      if (!silent) {
        showToast(`Gagal mengaktifkan notifikasi background: ${err?.message || 'Unknown error'}`)
      }
      return false
    } finally {
      setIsSubscribingPush(false)
    }
  }

  const disableBackgroundPush = async () => {
    setIsSubscribingPush(true)
    try {
      const reg = swRegistrationRef.current || (await navigator.serviceWorker?.getRegistration?.('/'))
      const sub = await reg?.pushManager?.getSubscription?.()
      if (sub) {
        const endpoint = sub.endpoint
        await sub.unsubscribe()
        await fetch('/api/push/subscribe', {
          method: 'DELETE',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ endpoint }),
        })
      }
      setPushStatus('prompt')
      setPrefNotification(false)
      showToast('Notifikasi latar belakang dinonaktifkan untuk perangkat ini.')
    } catch {
      setPrefNotification(false)
    } finally {
      setIsSubscribingPush(false)
    }
  }

  const sendTestBackgroundPush = async (delaySeconds = 5) => {
    setIsSendingTestPush(true)
    try {
      const ok = await enableBackgroundPush(true)
      if (!ok) return
      const reg = swRegistrationRef.current || (await navigator.serviceWorker.ready)
      const sub = await reg.pushManager.getSubscription()
      if (!sub) {
        showToast('Langganan push belum tersedia di perangkat ini.')
        return
      }
      const res = await fetch('/api/push/test', {
        method: 'POST',
        keepalive: true,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          subscription: sub.toJSON(),
          delaySeconds,
        }),
      })
      const json = await res.json().catch(() => ({}))
      if (!res.ok) {
        showToast(json?.error || 'Server gagal mengirim push test. Coba sinkronkan ulang.')
        return
      }
      if (delaySeconds > 0) {
        showToast(`Terjadwal di server! Sekarang tutup/swipe app & semua tab — notif masuk dalam ${delaySeconds} detik.`)
      } else {
        showToast('Push notif langsung terkirim ke perangkat ini!')
      }
    } catch {
      showToast('Gagal menghubungi server test push.')
    } finally {
      setIsSendingTestPush(false)
    }
  }

  // Sinkronisasi otomatis XP hunter & Daily All-Clear Bonus ke state serta profil cloud
  useEffect(() => {
    if (!mounted || !currentUser) return
    const prevBonusKey = (currentUser.dailyBonusDates || []).join(',')
    const nextBonusKey = effectiveDailyBonusDates.join(',')
    if (currentUser.xp !== effectiveXp || prevBonusKey !== nextBonusKey) {
      setUsers((prev) =>
        prev.map((u) =>
          u.id === currentUser.id || (currentUser.username && u.username === currentUser.username)
            ? { ...u, xp: effectiveXp, dailyBonusDates: effectiveDailyBonusDates }
            : u
        )
      )
      saveCloudProfile({ ...currentUser, xp: effectiveXp })
    }
  }, [mounted, currentUser?.id, currentUser?.username, effectiveXp, effectiveDailyBonusDates.join(',')])

  const currentWorkoutQuest = activeWorkoutQuest
    ? activeWorkoutQuest.type === 'personal'
      ? personalTasks.find((t) => t.id === activeWorkoutQuest.id)
      : clanQuests.find((cq) => cq.id === activeWorkoutQuest.id)
    : null

  const currentFinanceQuest = activeFinanceQuest
    ? personalTasks.find((t) => t.id === activeFinanceQuest.id) || null
    : null

  const isWorkoutViewOnly = Boolean(
    activeWorkoutQuest?.viewOnly ||
      (activeWorkoutQuest?.dateIso && activeWorkoutQuest.dateIso > todayIsoStr)
  )

  const rawWorkoutQuestExercises: WorkoutExercise[] = currentWorkoutQuest?.workoutExercises ?? []
  const workoutQuestExercises: WorkoutExercise[] = isWorkoutViewOnly
    ? rawWorkoutQuestExercises.map((ex) => ({
        ...ex,
        sets: ex.sets.map((s) => (s.completed ? { ...s, completed: false } : s)),
      }))
    : rawWorkoutQuestExercises
  const pendingWorkoutExercises = workoutQuestExercises.filter(
    (ex) => !(ex.sets.length > 0 && ex.sets.every((s) => s.completed))
  )
  const completedWorkoutExercises = workoutQuestExercises.filter(
    (ex) => ex.sets.length > 0 && ex.sets.every((s) => s.completed)
  )

  const totalWorkoutSets = workoutQuestExercises.reduce((acc, ex) => acc + ex.sets.length, 0)
  const completedWorkoutSets = workoutQuestExercises.reduce(
    (acc, ex) => acc + ex.sets.filter((s) => s.completed).length,
    0
  )
  const workoutProgressPct =
    totalWorkoutSets > 0 ? Math.round((completedWorkoutSets / totalWorkoutSets) * 100) : 0

  const activeExercise = activeExerciseId
    ? workoutQuestExercises.find((ex) => ex.id === activeExerciseId) || null
    : null

  useEffect(() => {
    if (activeExerciseId && chartScrollRef.current) {
      const timer = setTimeout(() => {
        if (chartScrollRef.current) {
          chartScrollRef.current.scrollTo({
            left: chartScrollRef.current.scrollWidth,
            behavior: 'smooth',
          })
        }
      }, 100)
      return () => clearTimeout(timer)
    }
  }, [activeExerciseId, activeExercise?.history?.length])

  const handleUpdateWorkoutExercises = (
    questId: string,
    type: 'personal' | 'clan',
    newExercises: WorkoutExercise[]
  ) => {
    const hasCompletedExercise = newExercises.some(
      (ex) => ex.sets.length > 0 && ex.sets.every((s) => s.completed)
    )

    if (type === 'personal') {
      const todayIso = getLocalIsoDate()
      const targetDateIso = activeWorkoutQuest?.dateIso || todayIso
      const target = personalTasks.find((t) => t.id === questId)
      const prevHadCompletedExercise = (target?.workoutExercises ?? []).some(
        (ex) => ex.sets.length > 0 && ex.sets.every((s) => s.completed)
      )
      const wasDoneOnTargetDate = Boolean(target?.completedDates?.includes(targetDateIso))

      const buildUpdatedTask = (t: PersonalTask): PersonalTask => {
        const prevCompleted = new Set(t.completedDates || [])
        const prevSkipped = new Set(t.skippedDates || [])

        if (hasCompletedExercise) {
          prevCompleted.add(targetDateIso)
          prevSkipped.delete(targetDateIso)
          prevSkipped.delete(`unskip:${targetDateIso}`)
        } else if (prevHadCompletedExercise && wasDoneOnTargetDate) {
          prevCompleted.delete(targetDateIso)
          if (targetDateIso < todayIso) {
            prevSkipped.add(`unskip:${targetDateIso}`)
          }
        }

        return {
          ...t,
          workoutExercises: newExercises,
          done: prevCompleted.has(todayIso),
          skipped: prevSkipped.has(todayIso),
          completedDates: Array.from(prevCompleted),
          skippedDates: Array.from(prevSkipped),
        }
      }

      setPersonalTasks((curr) =>
        curr.map((t) => (t.id === questId ? buildUpdatedTask(t) : t))
      )
      if (target) {
        saveCloudQuest(buildUpdatedTask(target), currentUser.username)
      }
    } else {
      setClanQuests((curr) =>
        curr.map((cq) => {
          if (cq.id !== questId) return cq
          const prevIds = new Set(cq.completedByUserIds || [])
          if (hasCompletedExercise && currentUser) {
            prevIds.add(currentUser.id)
          }
          return {
            ...cq,
            workoutExercises: newExercises,
            completedByUserIds: Array.from(prevIds),
          }
        })
      )
    }
  }

  const handleToggleWorkoutSet = (
    questId: string,
    type: 'personal' | 'clan',
    exerciseId: string,
    setId: string
  ) => {
    if (isWorkoutViewOnly) {
      showToast('🔒 Quest ini belum masuk jadwal harinya — hanya bisa melihat daftar gerakan.')
      return
    }
    const targetQuest =
      type === 'personal'
        ? personalTasks.find((t) => t.id === questId)
        : clanQuests.find((cq) => cq.id === questId)
    if (!targetQuest) return

    const wasAlreadyDone = Boolean(
      type === 'personal'
        ? (targetQuest as PersonalTask).done
        : currentUser && (targetQuest as ClanQuest).completedByUserIds.includes(currentUser.id)
    )
    const currentExs = targetQuest.workoutExercises ?? []
    let justCompleted = false
    let exerciseNowFinished = false
    let restTime = 60
    let recordedWeight = 0
    let recordedReps = 0
    let recordedSetNum = 1

    const updatedExs = currentExs.map((ex) => {
      if (ex.id !== exerciseId) return ex
      restTime = ex.restSeconds || 60
      const nextSets = ex.sets.map((s) => {
        if (s.id !== setId) return s
        const nextComp = !s.completed
        if (nextComp) {
          justCompleted = true
          recordedWeight = Number(s.weight) || 0
          recordedReps = Number(s.reps) || 10
          recordedSetNum = s.setNumber
        }
        return { ...s, completed: nextComp }
      })

      if (justCompleted && nextSets.length > 0 && nextSets.every((s) => s.completed)) {
        exerciseNowFinished = true
      }

      let nextHistory = ex.history ? [...ex.history] : undefined
      if (justCompleted) {
        const todayLabel = new Date().toLocaleDateString('id-ID', { day: '2-digit', month: 'short' })
        const hist = nextHistory ? [...nextHistory] : []
        const exIdx = hist.findIndex((h) => h.date === todayLabel)
        if (exIdx !== -1) {
          hist[exIdx] = { date: todayLabel, weight: recordedWeight, reps: recordedReps, setNumber: recordedSetNum }
        } else {
          hist.push({ date: todayLabel, weight: recordedWeight, reps: recordedReps, setNumber: recordedSetNum })
        }
        nextHistory = hist
      }

      return {
        ...ex,
        sets: nextSets,
        ...(nextHistory ? { history: nextHistory } : {}),
      }
    })

    handleUpdateWorkoutExercises(questId, type, updatedExs)

    if (justCompleted) {
      startRestCountdown(restTime)
      if (exerciseNowFinished && !wasAlreadyDone) {
        showToast(`🔥 Gerakan selesai! Quest "${targetQuest.title}" otomatis tercentang selesai!`)
      } else {
        showToast(`Set selesai! Istirahat ${restTime}s dimulai ⏳`)
      }
    }
  }

  // QUICK ADVANCE SET: Tap 1x = selesaikan 1 set berikutnya & otomatis mulai timer istirahat
  const handleQuickAdvanceSet = (
    questId: string,
    type: 'personal' | 'clan',
    exerciseId: string
  ) => {
    if (isWorkoutViewOnly) {
      showToast('🔒 Quest ini belum masuk jadwal harinya — hanya bisa melihat daftar gerakan.')
      return
    }
    const targetQuest =
      type === 'personal'
        ? personalTasks.find((t) => t.id === questId)
        : clanQuests.find((cq) => cq.id === questId)
    if (!targetQuest) return

    const wasAlreadyDone = Boolean(
      type === 'personal'
        ? (targetQuest as PersonalTask).done
        : currentUser && (targetQuest as ClanQuest).completedByUserIds.includes(currentUser.id)
    )
    const currentExs = targetQuest.workoutExercises ?? []
    let triggeredRest = false
    let restTime = 60
    let exName = ''
    let completedAfter = 0
    let totalSets = 0

    const updatedExs = currentExs.map((ex) => {
      if (ex.id !== exerciseId) return ex
      exName = ex.name
      restTime = ex.restSeconds || 60
      totalSets = ex.sets.length
      const nextIncompleteIdx = ex.sets.findIndex((s) => !s.completed)

      if (nextIncompleteIdx !== -1) {
        triggeredRest = true
        const completedSet = ex.sets[nextIncompleteIdx]
        const nextSets = ex.sets.map((s, idx) =>
          idx === nextIncompleteIdx ? { ...s, completed: true } : s
        )
        completedAfter = nextSets.filter((s) => s.completed).length

        const todayLabel = new Date().toLocaleDateString('id-ID', { day: '2-digit', month: 'short' })
        const hist = ex.history ? [...ex.history] : []
        const exIdx = hist.findIndex((h) => h.date === todayLabel)
        const histEntry = {
          date: todayLabel,
          weight: Number(completedSet.weight) || 0,
          reps: Number(completedSet.reps) || 10,
          setNumber: completedSet.setNumber,
        }
        if (exIdx !== -1) {
          hist[exIdx] = histEntry
        } else {
          hist.push(histEntry)
        }

        return { ...ex, sets: nextSets, history: hist }
      } else {
        // Jika semua set sudah selesai dan di-tap lagi, reset kembali ke 0
        triggeredRest = false
        completedAfter = 0
        return {
          ...ex,
          sets: ex.sets.map((s) => ({ ...s, completed: false })),
        }
      }
    })

    handleUpdateWorkoutExercises(questId, type, updatedExs)

    if (triggeredRest) {
      startRestCountdown(restTime)
      if (completedAfter === totalSets && !wasAlreadyDone) {
        showToast(`🔥 Gerakan "${exName}" selesai! Quest "${targetQuest.title}" otomatis tercentang selesai!`)
      } else if (completedAfter === totalSets) {
        showToast(`🔥 Semua set (${completedAfter}/${totalSets}) "${exName}" selesai! Istirahat ${restTime}s dimulai ⏳`)
      } else {
        showToast(`⚡ Set ${completedAfter}/${totalSets} "${exName}" selesai! Istirahat ${restTime}s dimulai ⏳`)
      }
    } else {
      stopRestCountdown(false)
      showToast(`Set "${exName}" direset kembali ke 0/${totalSets}.`)
    }
  }

  const handleUpdateSetField = (
    questId: string,
    type: 'personal' | 'clan',
    exerciseId: string,
    setId: string,
    field: 'reps' | 'weight',
    val: number | string
  ) => {
    const targetQuest =
      type === 'personal'
        ? personalTasks.find((t) => t.id === questId)
        : clanQuests.find((cq) => cq.id === questId)
    if (!targetQuest) return

    const currentExs = targetQuest.workoutExercises ?? []
    const updatedExs = currentExs.map((ex) => {
      if (ex.id !== exerciseId) return ex
      return {
        ...ex,
        sets: ex.sets.map((s) => (s.id === setId ? { ...s, [field]: val } : s)),
      }
    })
    handleUpdateWorkoutExercises(questId, type, updatedExs)
  }

  const handleAddSetToExercise = (questId: string, type: 'personal' | 'clan', exerciseId: string) => {
    const targetQuest =
      type === 'personal'
        ? personalTasks.find((t) => t.id === questId)
        : clanQuests.find((cq) => cq.id === questId)
    if (!targetQuest) return

    const currentExs = targetQuest.workoutExercises ?? []
    const updatedExs = currentExs.map((ex) => {
      if (ex.id !== exerciseId) return ex
      const nextSetNumber = ex.sets.length + 1
      const lastSet = ex.sets[ex.sets.length - 1]
      const newSet: WorkoutSet = {
        id: `set-${Date.now()}-${nextSetNumber}`,
        setNumber: nextSetNumber,
        reps: lastSet ? lastSet.reps : 10,
        weight: lastSet ? lastSet.weight : 20,
        completed: false,
      }
      return { ...ex, sets: [...ex.sets, newSet] }
    })
    handleUpdateWorkoutExercises(questId, type, updatedExs)
  }

  const handleDeleteSet = (
    questId: string,
    type: 'personal' | 'clan',
    exerciseId: string,
    setId: string
  ) => {
    const targetQuest =
      type === 'personal'
        ? personalTasks.find((t) => t.id === questId)
        : clanQuests.find((cq) => cq.id === questId)
    if (!targetQuest) return

    const currentExs = targetQuest.workoutExercises ?? []
    const updatedExs = currentExs.map((ex) => {
      if (ex.id !== exerciseId) return ex
      if (ex.sets.length <= 1) {
        showToast('Minimal 1 set dalam gerakan!')
        return ex
      }
      const filtered = ex.sets.filter((s) => s.id !== setId)
      const renumbered = filtered.map((s, idx) => ({ ...s, setNumber: idx + 1 }))
      return { ...ex, sets: renumbered }
    })
    handleUpdateWorkoutExercises(questId, type, updatedExs)
  }

  // CREATE GERAKAN
  const handleAddExercise = (
    questId: string,
    type: 'personal' | 'clan',
    name: string,
    restSeconds: number = 60,
    initialSetsCount: number = 3,
    initialReps: number = 10
  ) => {
    if (!name.trim()) return
    const targetQuest =
      type === 'personal'
        ? personalTasks.find((t) => t.id === questId)
        : clanQuests.find((cq) => cq.id === questId)
    if (!targetQuest) return

    const currentExs = targetQuest.workoutExercises ?? []
    const count = Math.max(1, Math.min(10, initialSetsCount))
    const targetReps = Math.max(1, initialReps || 10)
    const sets: WorkoutSet[] = []
    for (let i = 1; i <= count; i++) {
      sets.push({
        id: `set-${Date.now()}-${i}-${Math.random().toString(36).slice(2, 6)}`,
        setNumber: i,
        reps: targetReps,
        weight: 20,
        completed: false,
      })
    }
    const newEx: WorkoutExercise = {
      id: `ex-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
      name: name.trim(),
      restSeconds: restSeconds > 0 ? restSeconds : 60,
      sets,
    }
    handleUpdateWorkoutExercises(questId, type, [...currentExs, newEx])
    showToast(`Gerakan "${name.trim()}" (${count} × ${targetReps}) berhasil ditambahkan!`)
  }

  // HELPER: KONVERSI TEMPLATE SESI KE WORKOUT EXERCISES (DAPAT DIEDIT BEBAS OLEH USER)
  const buildWorkoutExercisesFromTemplate = (
    session: GymRoutineSessionTemplate
  ): WorkoutExercise[] => {
    const baseTs = Date.now()
    return session.exercises.map((item, exIdx) => {
      const setsCount = Math.max(1, item.sets || 3)
      const repsCount = Math.max(1, item.reps || 10)
      const sets: WorkoutSet[] = []
      for (let i = 1; i <= setsCount; i++) {
        sets.push({
          id: `set-${baseTs}-${exIdx}-${i}`,
          setNumber: i,
          reps: repsCount,
          weight: item.name.toLowerCase() === 'plank' ? 0 : 20,
          completed: false,
        })
      }
      return {
        id: `ex-${baseTs}-${exIdx}`,
        name: item.name,
        restSeconds: 60,
        sets,
      }
    })
  }

  // TERAPKAN TEMPLATE SESI KE WORKOUT YANG SEDANG DIBUKA
  const handleApplySessionToCurrentWorkout = (
    session: GymRoutineSessionTemplate,
    mode: 'replace' | 'append' = 'replace'
  ) => {
    if (!activeWorkoutQuest || !currentWorkoutQuest) return
    const built = buildWorkoutExercisesFromTemplate(session)
    const existing = currentWorkoutQuest.workoutExercises ?? []
    const nextExercises = mode === 'append' ? [...existing, ...built] : built
    handleUpdateWorkoutExercises(currentWorkoutQuest.id, activeWorkoutQuest.type, nextExercises)
    setIsGymLibraryModalOpen(false)
    setWorkoutSubPage('overview')
    showToast(
      `⚡ Referensi "${session.title}" (${built.length} gerakan) diterapkan! Kamu bebas mengubah/mengganti gerakan kapan saja.`
    )
  }

  // BUAT QUEST GYM BARU DARI 1 SESI REFERENSI
  const handleCreateQuestFromSessionTemplate = (session: GymRoutineSessionTemplate) => {
    const gymCat = findCategory('Gym')
    const builtExercises = buildWorkoutExercisesFromTemplate(session)
    const newTask: PersonalTask = {
      id: `pt-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
      userId: currentUser.id,
      title: session.questTitle,
      category: gymCat.name,
      xp: gymCat.xp,
      icon: gymCat.icon,
      done: false,
      schedule: session.recommendedDays.length > 0 ? session.recommendedDays : ['Everyday'],
      workoutExercises: builtExercises,
    }
    setPersonalTasks((curr) => [...curr, newTask])
    saveCloudQuest(newTask, currentUser.username)
    setIsGymLibraryModalOpen(false)
    setIsQuestProgramPageOpen(false)
    setWorkoutSubPage('overview')
    setActiveWorkoutQuest({ type: 'personal', id: newTask.id })
    showToast(
      `🔥 Quest "${session.questTitle}" berhasil dibuat dengan ${builtExercises.length} gerakan referensi! Semua bisa diedit bebas.`
    )
  }

  // TERAPKAN SELURUH JADWAL PROGRAM (2x / 3x / 4x / 5x / 6x SEMINGGU) KE MY QUEST
  const handleApplyFullProgramSchedule = (program: GymProgramTemplate) => {
    const gymCat = findCategory('Gym')
    const baseTs = Date.now()
    const createdTasks: PersonalTask[] = program.sessions.map((session, idx) => ({
      id: `pt-${baseTs}-${idx}`,
      userId: currentUser.id,
      title: session.questTitle,
      category: gymCat.name,
      xp: gymCat.xp,
      icon: gymCat.icon,
      done: false,
      schedule: session.recommendedDays.length > 0 ? session.recommendedDays : ['Everyday'],
      workoutExercises: buildWorkoutExercisesFromTemplate(session),
    }))

    setPersonalTasks((curr) => [...curr, ...createdTasks])
    saveAllCloudQuests(createdTasks, currentUser.username)
    const hasToday = createdTasks.some((t) => isQuestForToday(t.schedule))
    setQuestScheduleTab(hasToday ? 'today' : 'upcoming')
    setIsPersonalModalOpen(false)
    setIsGymLibraryModalOpen(false)
    setIsQuestProgramPageOpen(false)
    setWorkoutSubPage('overview')
    setActiveWorkoutQuest(null)
    setActiveTab('calendar')
    showToast(
      `🎉 Program "${program.frequencyLabel}" (${createdTasks.length} sesi) ditambahkan ke My Quest! Kamu bebas mengubah jadwal & gerakan kapan saja.`
    )
  }

  // UPDATE GERAKAN (EDIT NAMA & WAKTU ISTIRAHAT)
  const handleUpdateExercise = (
    questId: string,
    type: 'personal' | 'clan',
    exerciseId: string,
    newName: string,
    newRestSeconds: number
  ) => {
    if (!newName.trim()) return
    const targetQuest =
      type === 'personal'
        ? personalTasks.find((t) => t.id === questId)
        : clanQuests.find((cq) => cq.id === questId)
    if (!targetQuest) return

    const currentExs = targetQuest.workoutExercises ?? []
    const updatedExs = currentExs.map((ex) => {
      if (ex.id !== exerciseId) return ex
      return {
        ...ex,
        name: newName.trim(),
        restSeconds: newRestSeconds > 0 ? newRestSeconds : 60,
      }
    })
    handleUpdateWorkoutExercises(questId, type, updatedExs)
    setEditingExerciseId(null)
    showToast(`Gerakan diperbarui: "${newName.trim()}"`)
  }

  // LOG PROGRES BEBAN KE RIWAYAT TANGGAL (REAL-TIME)
  const handleLogExerciseProgress = (
    questId: string,
    type: 'personal' | 'clan',
    exerciseId: string,
    weight: number,
    reps: number,
    setsCount: number
  ) => {
    const targetQuest =
      type === 'personal'
        ? personalTasks.find((t) => t.id === questId)
        : clanQuests.find((cq) => cq.id === questId)
    if (!targetQuest) return

    const currentExs = targetQuest.workoutExercises ?? []
    const todayLabel = new Date().toLocaleDateString('id-ID', { day: '2-digit', month: 'short' })
    const updatedExs = currentExs.map((ex) => {
      if (ex.id !== exerciseId) return ex
      const prev = ex.history && ex.history.length > 0 ? [...ex.history] : []
      const existingIdx = prev.findIndex((h) => h.date === todayLabel)
      if (existingIdx !== -1) {
        prev[existingIdx] = { date: todayLabel, weight, reps, setNumber: setsCount, timestamp: Date.now() }
      } else {
        prev.push({ date: todayLabel, weight, reps, setNumber: setsCount, timestamp: Date.now() })
      }
      return { ...ex, history: prev }
    })
    handleUpdateWorkoutExercises(questId, type, updatedExs)
    showToast(`Beban ${weight}kg (${todayLabel}) berhasil dicatat ke riwayat!`)
  }

  // TAMBAH RIWAYAT SESI MANUAL / TANGGAL LAIN
  const handleAddCustomExerciseHistory = (
    questId: string,
    type: 'personal' | 'clan',
    exerciseId: string,
    dateStr: string,
    weight: number,
    reps: number = 10,
    setNum: number = 1
  ) => {
    if (!dateStr.trim() || weight <= 0) {
      showToast('Harap isi tanggal dan beban angka kg yang valid!')
      return
    }
    const targetQuest =
      type === 'personal'
        ? personalTasks.find((t) => t.id === questId)
        : clanQuests.find((cq) => cq.id === questId)
    if (!targetQuest) return

    const currentExs = targetQuest.workoutExercises ?? []
    const cleanDate = dateStr.trim()
    const updatedExs = currentExs.map((ex) => {
      if (ex.id !== exerciseId) return ex
      const prev = ex.history && ex.history.length > 0 ? [...ex.history] : []
      const existingIdx = prev.findIndex((h) => h.date.toLowerCase() === cleanDate.toLowerCase())
      const entry: WorkoutExerciseHistory = {
        date: cleanDate,
        weight: Number(weight),
        reps: Number(reps) || 10,
        setNumber: Number(setNum) || 1,
        timestamp: Date.now(),
      }
      if (existingIdx !== -1) {
        prev[existingIdx] = entry
      } else {
        prev.push(entry)
      }
      return { ...ex, history: prev }
    })
    handleUpdateWorkoutExercises(questId, type, updatedExs)
    showToast(`Sesi ${cleanDate} (${weight}kg) berhasil ditambahkan ke riwayat!`)
    setCustomHistDate('')
    setCustomHistWeight('')
  }

  // HAPUS RIWAYAT SESI
  const handleDeleteExerciseHistory = (
    questId: string,
    type: 'personal' | 'clan',
    exerciseId: string,
    historyIdx: number
  ) => {
    const targetQuest =
      type === 'personal'
        ? personalTasks.find((t) => t.id === questId)
        : clanQuests.find((cq) => cq.id === questId)
    if (!targetQuest) return

    const currentExs = targetQuest.workoutExercises ?? []
    const updatedExs = currentExs.map((ex) => {
      if (ex.id !== exerciseId || !ex.history) return ex
      const filtered = ex.history.filter((_, idx) => idx !== historyIdx)
      return { ...ex, history: filtered }
    })
    handleUpdateWorkoutExercises(questId, type, updatedExs)
    showToast('Catatan riwayat beban dihapus.')
  }

  // DELETE GERAKAN
  const handleDeleteExercise = (questId: string, type: 'personal' | 'clan', exerciseId: string) => {
    const targetQuest =
      type === 'personal'
        ? personalTasks.find((t) => t.id === questId)
        : clanQuests.find((cq) => cq.id === questId)
    if (!targetQuest) return

    const currentExs = targetQuest.workoutExercises ?? []
    const updatedExs = currentExs.filter((ex) => ex.id !== exerciseId)
    handleUpdateWorkoutExercises(questId, type, updatedExs)
    if (activeExerciseId === exerciseId) {
      setActiveExerciseId(null)
    }
    showToast('Gerakan dihapus dari workout.')
  }

  // CLEAR ALL GERAKAN (KOSONGKAN WORKOUT)
  const handleClearAllExercises = (questId: string, type: 'personal' | 'clan') => {
    handleUpdateWorkoutExercises(questId, type, [])
    setActiveExerciseId(null)
    showToast('Semua gerakan latihan dikosongkan.')
  }

  const handleCompleteWorkout = (questId: string, type: 'personal' | 'clan') => {
    if (isWorkoutViewOnly) {
      showToast('🔒 Quest ini belum masuk jadwal harinya — hanya bisa melihat daftar gerakan.')
      return
    }
    // Sinkronkan seluruh beban gerakan yang set-nya selesai ke riwayat real-time hari ini
    const targetQuest =
      type === 'personal'
        ? personalTasks.find((t) => t.id === questId)
        : clanQuests.find((cq) => cq.id === questId)

    const targetDateIso = activeWorkoutQuest?.dateIso || getLocalIsoDate()
    const targetDateObj = new Date(`${targetDateIso}T00:00:00`)

    if (targetQuest && targetQuest.workoutExercises) {
      const dateLabelForHist = !isNaN(targetDateObj.getTime())
        ? targetDateObj.toLocaleDateString('id-ID', { day: '2-digit', month: 'short' })
        : new Date().toLocaleDateString('id-ID', { day: '2-digit', month: 'short' })
      const updatedExercises = targetQuest.workoutExercises.map((ex) => {
        const completedSets = ex.sets.filter((s) => s.completed)
        if (completedSets.length === 0) return ex
        const lastCompleted = completedSets[completedSets.length - 1]
        const prevHist = ex.history ? [...ex.history] : []
        const exIdx = prevHist.findIndex((h) => h.date === dateLabelForHist)
        const histEntry: WorkoutExerciseHistory = {
          date: dateLabelForHist,
          weight: Number(lastCompleted.weight) || 0,
          reps: Number(lastCompleted.reps) || 10,
          setNumber: lastCompleted.setNumber,
          timestamp: Date.now(),
        }
        if (exIdx !== -1) {
          prevHist[exIdx] = histEntry
        } else {
          prevHist.push(histEntry)
        }
        return { ...ex, history: prevHist }
      })
      handleUpdateWorkoutExercises(questId, type, updatedExercises)
    }

    const hasCompletedExerciseInSession = Boolean(
      targetQuest?.workoutExercises?.some(
        (ex) => ex.sets.length > 0 && ex.sets.every((s) => s.completed)
      )
    )

    if (!hasCompletedExerciseInSession) {
      if (type === 'personal') {
        const target = personalTasks.find((t) => t.id === questId)
        if (target && !target.completedDates?.includes(targetDateIso)) {
          handleTogglePersonal(questId, targetDateIso)
        }
      } else {
        const target = clanQuests.find((cq) => cq.id === questId)
        if (target && !target.completedByUserIds.includes(currentUser.id)) {
          handleToggleClanQuest(target)
        }
      }
    }
    setActiveWorkoutQuest(null)
    setActiveExerciseId(null)
    stopRestCountdown(false)
    showToast('🎉 Sesi Workout Selesai! Riwayat beban berhasil diperbarui!')
  }

  // ============================================================================
  // AFTER-GYM PROGRESS PHOTO & TIMELAPSE VIDEO GENERATOR
  // ============================================================================

  const userGymPhotos = gymProgressPhotos
    .filter(
      (p) =>
        p.userId === currentUser.id ||
        (currentUser.username && p.userId === currentUser.username)
    )
    .sort((a, b) => a.dateIso.localeCompare(b.dateIso) || a.createdAt - b.createdAt)

  const openPhotoCropper = (opts: {
    imageSrc: string
    aspectRatio: '3/4' | '1/1'
    isCircular?: boolean
    target: 'gym-new' | 'gym-replace' | 'gym-edit' | 'profile-avatar'
    targetPhotoId?: string
    title: string
  }) => {
    const img = new Image()
    img.onload = () => {
      setCropImgNatural({ w: img.width || 1, h: img.height || 1 })
      setCropZoom(1)
      setCropOffset({ x: 0, y: 0 })
      setCropRotation(0)
      setCropModal({
        isOpen: true,
        ...opts,
      })
    }
    img.src = opts.imageSrc
  }

  const handleApplyCropModal = () => {
    if (!cropModal) return
    const img = new Image()
    img.onload = () => {
      const isSquare = cropModal.aspectRatio === '1/1'
      const boxW = isSquare ? 280 : 270
      const boxH = isSquare ? 280 : 360
      const outW = isSquare ? 320 : 540
      const outH = isSquare ? 320 : 720
      const ratio = outW / boxW

      const isRotatedOdd = cropRotation % 180 !== 0
      const rotW = isRotatedOdd ? img.height : img.width
      const rotH = isRotatedOdd ? img.width : img.height
      const baseScale = Math.max(boxW / rotW, boxH / rotH)

      const canvas = document.createElement('canvas')
      canvas.width = outW
      canvas.height = outH
      const ctx = canvas.getContext('2d')
      if (!ctx) return

      ctx.fillStyle = '#070410'
      ctx.fillRect(0, 0, outW, outH)
      ctx.save()
      ctx.translate(outW / 2 + cropOffset.x * ratio, outH / 2 + cropOffset.y * ratio)
      ctx.scale(cropZoom * ratio * baseScale, cropZoom * ratio * baseScale)
      ctx.rotate((cropRotation * Math.PI) / 180)
      ctx.drawImage(img, -img.width / 2, -img.height / 2)
      ctx.restore()

      const dataUrl = canvas.toDataURL('image/jpeg', 0.85)

      if (cropModal.target === 'profile-avatar') {
        const updatedUser = { ...currentUser, avatarUrl: dataUrl }
        setUsers((prev) => prev.map((u) => (u.id === currentUser.id ? updatedUser : u)))
        saveCloudProfile(updatedUser)
        showToast('Foto profil berhasil diperbarui!')
      } else if (cropModal.target === 'gym-new') {
        const newPhoto = {
          id: `gphoto-${Date.now()}`,
          userId: currentUser.id,
          dateIso: photoUploadDate || getLocalIsoDate(),
          questTitle: currentWorkoutQuest?.title || 'Gym Workout',
          dataUrl,
          createdAt: Date.now(),
        }
        setGymProgressPhotos((prev) => {
          const next = [...prev, newPhoto]
          const nextUserPhotos = next.filter(
            (p) =>
              p.userId === currentUser.id ||
              (currentUser.username && p.userId === currentUser.username)
          )
          setActiveGymPhotoIdx(Math.max(0, nextUserPhotos.length - 1))
          return next
        })
        setTimelapseVideoUrl(null)
        showToast('📸 Foto After-Gym berhasil disimpan!')
      } else if (
        (cropModal.target === 'gym-replace' || cropModal.target === 'gym-edit') &&
        cropModal.targetPhotoId
      ) {
        setGymProgressPhotos((prev) =>
          prev.map((p) => (p.id === cropModal.targetPhotoId ? { ...p, dataUrl } : p))
        )
        setTimelapseVideoUrl(null)
        showToast(
          cropModal.target === 'gym-replace'
            ? '🔄 Foto berhasil diganti!'
            : '✂️ Foto berhasil disesuaikan!'
        )
      }

      setCropModal(null)
    }
    img.src = cropModal.imageSrc
  }

  const handleUploadGymPhoto = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    e.target.value = ''
    if (!file) return

    const reader = new FileReader()
    reader.onload = () => {
      if (typeof reader.result === 'string') {
        openPhotoCropper({
          imageSrc: reader.result,
          aspectRatio: '3/4',
          target: 'gym-new',
          title: 'Atur & Crop Foto After-Gym',
        })
      }
    }
    reader.readAsDataURL(file)
  }

  const handleReplaceGymPhotoFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    e.target.value = ''
    if (!file || !replacingGymPhotoId) return

    const targetId = replacingGymPhotoId
    setReplacingGymPhotoId(null)

    const reader = new FileReader()
    reader.onload = () => {
      if (typeof reader.result === 'string') {
        openPhotoCropper({
          imageSrc: reader.result,
          aspectRatio: '3/4',
          target: 'gym-replace',
          targetPhotoId: targetId,
          title: 'Ganti & Crop Foto',
        })
      }
    }
    reader.readAsDataURL(file)
  }

  const stopLiveCamera = () => {
    if (cameraStreamRef.current) {
      cameraStreamRef.current.getTracks().forEach((t) => t.stop())
      cameraStreamRef.current = null
    }
    setIsCameraOpen(false)
  }

  const startLiveCamera = async (facing: 'user' | 'environment' = cameraFacingMode) => {
    if (cameraStreamRef.current) {
      cameraStreamRef.current.getTracks().forEach((t) => t.stop())
      cameraStreamRef.current = null
    }
    if (typeof navigator === 'undefined' || !navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      gymCameraInputRef.current?.click()
      return
    }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: facing },
        audio: false,
      })
      cameraStreamRef.current = stream
      setCameraFacingMode(facing)
      setIsCameraOpen(true)
    } catch {
      // Fallback ke input kamera native jika akses WebRTC ditolak / tidak tersedia
      gymCameraInputRef.current?.click()
    }
  }

  const flipLiveCamera = () => {
    const nextFacing = cameraFacingMode === 'environment' ? 'user' : 'environment'
    startLiveCamera(nextFacing)
  }

  const captureLivePhoto = () => {
    const video = cameraVideoRef.current
    if (!video || !video.videoWidth || !video.videoHeight) return
    const canvas = document.createElement('canvas')
    canvas.width = video.videoWidth
    canvas.height = video.videoHeight
    const ctx = canvas.getContext('2d')
    if (!ctx) return
    if (cameraFacingMode === 'user') {
      ctx.translate(canvas.width, 0)
      ctx.scale(-1, 1)
    }
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height)
    const rawDataUrl = canvas.toDataURL('image/jpeg', 0.92)
    stopLiveCamera()
    openPhotoCropper({
      imageSrc: rawDataUrl,
      aspectRatio: '3/4',
      target: 'gym-new',
      title: 'Atur & Crop Foto Kamera',
    })
  }

  const handleDeleteGymPhoto = (photoId: string) => {
    setGymProgressPhotos((prev) => prev.filter((p) => p.id !== photoId))
    setActiveGymPhotoIdx((prev) => Math.max(0, prev - 1))
    setTimelapseVideoUrl(null)
    showToast('Foto progres dihapus.')
  }

  const toggleTimelapsePlayback = () => {
    if (isPlayingTimelapse) {
      if (liveFlipTimerRef.current) {
        clearInterval(liveFlipTimerRef.current)
        liveFlipTimerRef.current = null
      }
      setIsPlayingTimelapse(false)
      setLiveFlipIdx(null)
      return
    }
    if (userGymPhotos.length === 0) return
    setIsPlayingTimelapse(true)
    let idx = activeGymPhotoIdx % userGymPhotos.length
    setActiveGymPhotoIdx(idx)
    setLiveFlipIdx(idx)
    liveFlipTimerRef.current = setInterval(() => {
      idx = (idx + 1) % userGymPhotos.length
      setActiveGymPhotoIdx(idx)
      setLiveFlipIdx(idx)
    }, timelapseSpeedMs)
  }

  const changeTimelapseSpeed = (spdMs: number) => {
    setTimelapseSpeedMs(spdMs)
    if (isPlayingTimelapse && liveFlipTimerRef.current) {
      clearInterval(liveFlipTimerRef.current)
      let idx = activeGymPhotoIdx % userGymPhotos.length
      liveFlipTimerRef.current = setInterval(() => {
        idx = (idx + 1) % userGymPhotos.length
        setActiveGymPhotoIdx(idx)
        setLiveFlipIdx(idx)
      }, spdMs)
    }
  }

  const toggleLiveFlipPreview = toggleTimelapsePlayback

  const handleGenerateTimelapseVideo = async () => {
    if (userGymPhotos.length < 2) {
      showToast('Tambahkan minimal 2 foto berbeda hari untuk membuat video timelapse!')
      return
    }
    if (typeof MediaRecorder === 'undefined') {
      showToast('Browser tidak mendukung perekaman video otomatis.')
      return
    }

    if (liveFlipTimerRef.current) {
      clearInterval(liveFlipTimerRef.current)
      liveFlipTimerRef.current = null
      setIsPlayingTimelapse(false)
      setLiveFlipIdx(null)
    }

    setIsGeneratingTimelapse(true)
    try {
      const canvas = document.createElement('canvas')
      canvas.width = 540
      canvas.height = 720
      const ctx = canvas.getContext('2d')
      if (!ctx) throw new Error('Canvas 2D unavailable')

      // Load all images first
      const loadedImgs = await Promise.all(
        userGymPhotos.map(
          (p) =>
            new Promise<HTMLImageElement>((resolve, reject) => {
              const im = new Image()
              im.onload = () => resolve(im)
              im.onerror = reject
              im.src = p.dataUrl
            })
        )
      )

      const mimeCandidates = [
        'video/webm;codecs=vp8',
        'video/webm;codecs=vp9',
        'video/webm',
        'video/mp4',
      ]
      const supportedMime = mimeCandidates.find((m) => MediaRecorder.isTypeSupported(m)) || ''
      const isMp4 = supportedMime.includes('mp4')
      const ext = isMp4 ? 'mp4' : 'webm'
      setTimelapseVideoExt(ext)

      const drawFrame = (im: HTMLImageElement, photo: typeof userGymPhotos[number], dayNum: number) => {
        ctx.fillStyle = '#070410'
        ctx.fillRect(0, 0, canvas.width, canvas.height)

        // Center-crop cover fit
        const scale = Math.max(canvas.width / im.width, canvas.height / im.height)
        const dw = im.width * scale
        const dh = im.height * scale
        const dx = (canvas.width - dw) / 2
        const dy = (canvas.height - dh) / 2
        ctx.drawImage(im, dx, dy, dw, dh)

        // Bottom dark gradient overlay
        const grad = ctx.createLinearGradient(0, canvas.height - 180, 0, canvas.height)
        grad.addColorStop(0, 'rgba(7, 4, 16, 0)')
        grad.addColorStop(0.5, 'rgba(7, 4, 16, 0.72)')
        grad.addColorStop(1, 'rgba(7, 4, 16, 0.94)')
        ctx.fillStyle = grad
        ctx.fillRect(0, canvas.height - 180, canvas.width, 180)

        // Day pill
        ctx.fillStyle = 'rgba(124, 58, 237, 0.92)'
        ctx.fillRect(24, canvas.height - 96, 86, 28)
        ctx.fillStyle = '#ffffff'
        ctx.font = 'bold 14px Inter, sans-serif'
        ctx.fillText(`DAY #${dayNum}`, 36, canvas.height - 77)

        // Date & Quest title
        const parsed = new Date(`${photo.dateIso}T00:00:00`)
        const prettyDate = !isNaN(parsed.getTime())
          ? parsed.toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' })
          : photo.dateIso
        ctx.fillStyle = '#f5f2ff'
        ctx.font = 'bold 22px Inter, sans-serif'
        ctx.fillText(prettyDate, 24, canvas.height - 44)

        ctx.fillStyle = '#67e8f9'
        ctx.font = 'bold 13px Inter, sans-serif'
        ctx.fillText(`RANKERZ • ${photo.questTitle.toUpperCase()}`, 24, canvas.height - 18)
      }

      // Render frame awal sebelum start agar stream langsung memiliki frame valid
      drawFrame(loadedImgs[0], userGymPhotos[0], 1)

      const stream = canvas.captureStream(30)
      const recorder = supportedMime
        ? new MediaRecorder(stream, { mimeType: supportedMime, videoBitsPerSecond: 2_500_000 })
        : new MediaRecorder(stream)
      const chunks: BlobPart[] = []
      recorder.ondataavailable = (ev) => {
        if (ev.data && ev.data.size > 0) chunks.push(ev.data)
      }

      const donePromise = new Promise<Blob>((resolve) => {
        recorder.onstop = () => {
          resolve(new Blob(chunks, { type: supportedMime || recorder.mimeType || 'video/webm' }))
        }
      })

      recorder.start(100)

      // Pump frames continuously at ~30fps so MediaRecorder captures every photo reliably
      let activeRecIdx = 0
      let isRecording = true
      const pumpFrames = () => {
        if (!isRecording) return
        drawFrame(loadedImgs[activeRecIdx], userGymPhotos[activeRecIdx], activeRecIdx + 1)
        requestAnimationFrame(pumpFrames)
      }
      requestAnimationFrame(pumpFrames)

      for (let i = 0; i < loadedImgs.length; i++) {
        activeRecIdx = i
        await new Promise((r) => setTimeout(r, timelapseSpeedMs))
      }

      // Tambah jeda singkat agar frame terakhir terekam utuh sebelum stop
      await new Promise((r) => setTimeout(r, 150))
      isRecording = false
      recorder.stop()

      const videoBlob = await donePromise
      if (videoBlob.size === 0) {
        throw new Error('Empty video blob generated')
      }
      if (timelapseVideoUrl) {
        URL.revokeObjectURL(timelapseVideoUrl)
      }
      const url = URL.createObjectURL(videoBlob)
      setTimelapseVideoUrl(url)

      // Auto trigger download langsung tanpa perlu card player kaku
      const downloadLink = document.createElement('a')
      downloadLink.href = url
      downloadLink.download = `rankerz-timelapse-${getLocalIsoDate()}.${ext}`
      document.body.appendChild(downloadLink)
      downloadLink.click()
      document.body.removeChild(downloadLink)

      showToast('🎬 Video timelapse berhasil di-download!')
    } catch (err) {
      console.error(err)
      showToast('Gagal membuat video timelapse. Coba gunakan browser Chrome/Edge.')
    } finally {
      setIsGeneratingTimelapse(false)
    }
  }

  // ============================================================================
  // FINANCE VAULT HANDLERS (PENGHASILAN, BUDGET POS & SAVING GOALS)
  // ============================================================================

  const formatRupiah = (amount: number): string => {
    return `Rp ${Math.round(amount || 0).toLocaleString('id-ID')}`
  }

  const formatRupiahCompact = (amount: number): string => {
    const val = Math.round(amount || 0)
    if (val >= 1000000) {
      const jt = val / 1000000
      return `Rp ${Number.isInteger(jt) ? jt : jt.toFixed(1).replace('.', ',')} Jt`
    }
    if (val >= 1000) {
      return `Rp ${Math.round(val / 1000)} Rb`
    }
    return formatRupiah(val)
  }

  const formatDigitsWithDots = (raw: string | number): string => {
    const digits = String(raw ?? '').replace(/\D/g, '')
    if (!digits) return ''
    const num = parseInt(digits, 10)
    if (Number.isNaN(num)) return ''
    return num.toLocaleString('id-ID')
  }

  const parseFormattedDigits = (raw: string | number): number => {
    const digits = String(raw ?? '').replace(/\D/g, '')
    if (!digits) return 0
    return Math.max(0, parseInt(digits, 10) || 0)
  }

  const persistFinanceVault = (nextVault: FinanceVaultState) => {
    const stamped: FinanceVaultState = { ...nextVault, updatedAt: Date.now() }
    setFinanceVault(stamped)
    if (typeof window !== 'undefined' && currentUser?.id) {
      try {
        localStorage.setItem(`solo_finance_vault_v1_${currentUser.id}`, JSON.stringify(stamped))
      } catch (e) {
        console.error(e)
      }
    }
    if (currentUser?.id && isSupabaseConfigured) {
      saveCloudFinanceVault(currentUser.id, currentUser.username, stamped)
    }
  }

  const spawnFinanceParticle = (text: string) => {
    const id = `fp-${Date.now()}-${Math.random().toString(36).slice(2, 5)}`
    setFinanceParticles((prev) => [...prev, { id, text }])
    setTimeout(() => {
      setFinanceParticles((prev) => prev.filter((p) => p.id !== id))
    }, 950)
  }

  const handleSaveMonthlyIncome = (newAmountRaw: number) => {
    const amount = Math.max(0, Math.round(Number(newAmountRaw) || 0))
    persistFinanceVault({
      ...financeVault,
      monthlyIncome: amount,
    })
    setMonthlyIncomeDraft(amount > 0 ? formatDigitsWithDots(amount) : '')
    setIsEditingMonthlyIncome(false)
    setActiveFinanceSheet(null)
    if (amount <= 0) {
      showToast('Gaji / Penghasilan utama dikosongkan (Rp 0)')
    } else {
      spawnFinanceParticle(`Gaji ${formatRupiah(amount)}`)
      showToast(`Penghasilan bulanan diatur: ${formatRupiah(amount)}`)
    }
  }

  const handleCompleteFinanceQuest = (taskId: string, targetDateIso?: string) => {
    const dateIso = targetDateIso || getLocalIsoDate()
    const target = personalTasks.find((t) => t.id === taskId)
    if (!target) return
    if (target.completedDates?.includes(dateIso)) {
      showToast('Quest keuangan hari ini sudah tuntas! (+XP sudah diklaim)')
      return
    }
    handleTogglePersonal(taskId, dateIso)
  }

  const handleQuickSaveToGoal = (goalId: string, amount: number, questId?: string, dateIso?: string) => {
    if (amount <= 0) return
    const targetIso = dateIso || getLocalIsoDate()
    const goal = financeVault.goals.find((g) => g.id === goalId)
    if (!goal) return

    const newLog: FinanceLogItem = {
      id: `flog-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
      type: 'saving',
      amount,
      goalId,
      note: `Nabung ke ${goal.title}`,
      dateIso: targetIso,
      createdAt: Date.now(),
    }

    const updatedGoals = financeVault.goals.map((g) =>
      g.id === goalId ? { ...g, savedAmount: g.savedAmount + amount } : g
    )

    persistFinanceVault({
      ...financeVault,
      goals: updatedGoals,
      logs: [newLog, ...financeVault.logs].slice(0, 120),
    })

    if (questId) {
      const q = personalTasks.find((t) => t.id === questId)
      if (q && !q.completedDates?.includes(targetIso) && targetIso <= getLocalIsoDate()) {
        handleTogglePersonal(questId, targetIso)
      }
    }
    spawnFinanceParticle(`+${formatRupiah(amount)}`)
    showToast(`Berhasil menabung +${formatRupiah(amount)} ke ${goal.title}!`)
  }

  const handleAddFinanceLog = (questId?: string, targetDateIso?: string) => {
    const parsedAmount = parseFormattedDigits(financeAmountInput)
    if (parsedAmount <= 0) {
      showToast('Nominal transaksi harus lebih dari Rp 0')
      return
    }

    const dateIso = targetDateIso || getLocalIsoDate()
    const selectedGoal = financeVault.goals.find((g) => g.id === financeSelectedGoalId) || financeVault.goals[0]
    const selectedBucket = financeVault.buckets.find((b) => b.id === financeSelectedBucketId) || financeVault.buckets[0]

    const newLog: FinanceLogItem = {
      id: `flog-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
      type: financeLogType,
      amount: parsedAmount,
      bucketId: financeLogType === 'expense' ? selectedBucket?.id : undefined,
      goalId: financeLogType === 'saving' ? selectedGoal?.id : undefined,
      note:
        financeNoteInput.trim() ||
        (financeLogType === 'saving'
          ? `Nabung ke ${selectedGoal?.title || 'Tabungan'}`
          : financeLogType === 'expense'
            ? `Pengeluaran ${selectedBucket?.name || 'Harian'}`
            : 'Pemasukan tambahan'),
      dateIso,
      createdAt: Date.now(),
    }

    const updatedGoals =
      financeLogType === 'saving' && selectedGoal
        ? financeVault.goals.map((g) =>
            g.id === selectedGoal.id ? { ...g, savedAmount: g.savedAmount + parsedAmount } : g
          )
        : financeVault.goals

    persistFinanceVault({
      ...financeVault,
      goals: updatedGoals,
      logs: [newLog, ...financeVault.logs].slice(0, 120),
    })

    setFinanceAmountInput('')
    setFinanceNoteInput('')
    setActiveFinanceSheet(null)
    spawnFinanceParticle(`${financeLogType === 'expense' ? '-' : '+'}${formatRupiah(parsedAmount)}`)

    let completedNow = false
    if (financeLogType === 'saving' && questId) {
      const q = personalTasks.find((t) => t.id === questId)
      if (q && !q.completedDates?.includes(dateIso) && dateIso <= getLocalIsoDate()) {
        handleTogglePersonal(questId, dateIso)
        completedNow = true
      }
    }

    if (completedNow) {
      showToast(`Tercatat ${formatRupiah(parsedAmount)} & Quest Keuangan Tuntas!`)
    } else {
      showToast(
        financeLogType === 'saving'
          ? `Tabungan +${formatRupiah(parsedAmount)} disimpan ke Vault!`
          : financeLogType === 'expense'
            ? `Pengeluaran ${formatRupiah(parsedAmount)} tercatat.`
            : `Pemasukan +${formatRupiah(parsedAmount)} tercatat.`
      )
    }
  }

  const handleDeleteFinanceLog = (logId: string) => {
    const targetLog = financeVault.logs.find((l) => l.id === logId)
    if (!targetLog) return
    const updatedGoals =
      targetLog.type === 'saving' && targetLog.goalId
        ? financeVault.goals.map((g) =>
            g.id === targetLog.goalId
              ? { ...g, savedAmount: Math.max(0, g.savedAmount - targetLog.amount) }
              : g
          )
        : financeVault.goals

    persistFinanceVault({
      ...financeVault,
      goals: updatedGoals,
      logs: financeVault.logs.filter((l) => l.id !== logId),
    })
    showToast('Catatan transaksi dihapus.')
  }

  const handleUpdateFinanceLog = (logId: string) => {
    const targetLog = financeVault.logs.find((l) => l.id === logId)
    if (!targetLog) return

    const newAmount = parseFormattedDigits(editingLogAmountDraft)
    if (newAmount <= 0) {
      showToast('Nominal harus lebih dari Rp 0')
      return
    }

    const note = editingLogNoteDraft.trim() || (editingLogTypeDraft === 'saving' ? 'Tabungan' : editingLogTypeDraft === 'income' ? 'Pemasukan' : 'Pengeluaran')

    let updatedGoals = [...financeVault.goals]

    if (targetLog.type === 'saving' && targetLog.goalId) {
      updatedGoals = updatedGoals.map((g) =>
        g.id === targetLog.goalId
          ? { ...g, savedAmount: Math.max(0, g.savedAmount - targetLog.amount) }
          : g
      )
    }

    if (editingLogTypeDraft === 'saving' && editingLogGoalDraft) {
      updatedGoals = updatedGoals.map((g) =>
        g.id === editingLogGoalDraft
          ? { ...g, savedAmount: g.savedAmount + newAmount }
          : g
      )
    }

    const updatedLogs = financeVault.logs.map((l) =>
      l.id === logId
        ? {
            ...l,
            type: editingLogTypeDraft,
            amount: newAmount,
            note,
            bucketId: editingLogTypeDraft === 'expense' ? editingLogBucketDraft : undefined,
            goalId: editingLogTypeDraft === 'saving' ? editingLogGoalDraft : undefined,
            dateIso: editingLogDateDraft || l.dateIso,
          }
        : l
    )

    persistFinanceVault({
      ...financeVault,
      goals: updatedGoals,
      logs: updatedLogs,
    })

    setActiveFinanceSheet(null)
    setEditingLogId(null)
    showToast('Transaksi berhasil diperbarui.')
  }

  const handleAddFinanceBucket = () => {
    const name = newBucketName.trim()
    const target = parseFormattedDigits(newBucketTarget)
    if (!name || target <= 0) {
      showToast('Isi nama pos dan batas anggaran (> Rp 0)')
      return
    }
    const colorMap: Record<FinanceBudgetBucket['category'], string> = {
      kebutuhan: '#38bdf8',
      hiburan: '#f59e0b',
      tabungan: '#10b981',
      cicilan: '#f43f5e',
    }
    const newBucket: FinanceBudgetBucket = {
      id: `fbucket-${Date.now()}`,
      name,
      category: newBucketCategory,
      targetMonthly: target,
      color: colorMap[newBucketCategory],
    }
    persistFinanceVault({
      ...financeVault,
      buckets: [...financeVault.buckets, newBucket],
    })
    setFinanceSelectedBucketId(newBucket.id)
    setNewBucketName('')
    setNewBucketTarget('')
    setIsAddingFinanceBucket(false)
    setActiveFinanceSheet(null)
    setFinanceTab('budget')
    spawnFinanceParticle('+ Pos Baru')
    showToast(`Pos pengeluaran "${name}" ditambahkan!`)
  }

  const handleUpdateFinanceBucketTarget = (bucketId: string, nextTarget: number, nextName?: string) => {
    const trimmedName = (nextName ?? '').trim()
    if (nextName !== undefined && !trimmedName) {
      showToast('Nama pos tidak boleh kosong')
      return
    }
    const clean = Math.max(10000, Math.round(nextTarget))
    persistFinanceVault({
      ...financeVault,
      buckets: financeVault.buckets.map((b) =>
        b.id === bucketId
          ? { ...b, name: trimmedName || b.name, targetMonthly: clean }
          : b
      ),
    })
    setEditingBucketId(null)
    setActiveFinanceSheet(null)
    showToast(`Pos "${trimmedName || 'anggaran'}" diperbarui: ${formatRupiah(clean)}`)
  }

  const handleDeleteFinanceBucket = (bucketId: string) => {
    if (financeVault.buckets.length <= 1) {
      showToast('Minimal harus ada 1 pos anggaran')
      return
    }
    const nextBuckets = financeVault.buckets.filter((b) => b.id !== bucketId)
    persistFinanceVault({
      ...financeVault,
      buckets: nextBuckets,
    })
    if (financeSelectedBucketId === bucketId && nextBuckets[0]) {
      setFinanceSelectedBucketId(nextBuckets[0].id)
    }
    showToast('Pos anggaran dihapus.')
  }

  const handleAddFinanceGoal = () => {
    const title = newGoalTitle.trim()
    const target = parseFormattedDigits(newGoalTarget)
    const saved = parseFormattedDigits(newGoalSaved)
    if (!title || target <= 0) {
      showToast('Isi nama target tabungan & nominal target (> Rp 0)')
      return
    }
    const newGoal: FinanceSavingGoal = {
      id: `fgoal-${Date.now()}`,
      title,
      targetAmount: target,
      savedAmount: saved,
      note: newGoalNote.trim() || undefined,
    }
    persistFinanceVault({
      ...financeVault,
      goals: [...financeVault.goals, newGoal],
    })
    setFinanceSelectedGoalId(newGoal.id)
    setNewGoalTitle('')
    setNewGoalTarget('')
    setNewGoalSaved('0')
    setNewGoalNote('')
    setIsAddingFinanceGoal(false)
    setActiveFinanceSheet(null)
    setFinanceTab('goals')
    spawnFinanceParticle('+ Target Baru')
    showToast(`Target tabungan "${title}" dibuat!`)
  }

  const handleUpdateFinanceGoal = (goalId: string) => {
    const title = editingGoalTitleDraft.trim()
    const target = parseFormattedDigits(editingGoalTargetDraft)
    const saved = parseFormattedDigits(editingGoalSavedDraft)
    if (!title || target <= 0) {
      showToast('Nama target dan nominal target harus valid (> Rp 0)')
      return
    }
    persistFinanceVault({
      ...financeVault,
      goals: financeVault.goals.map((g) =>
        g.id === goalId ? { ...g, title, targetAmount: target, savedAmount: saved } : g
      ),
    })
    setEditingGoalId(null)
    setActiveFinanceSheet(null)
    showToast(`Target "${title}" diperbarui!`)
  }

  const handleDeleteFinanceGoal = (goalId: string) => {
    const nextGoals = financeVault.goals.filter((g) => g.id !== goalId)
    persistFinanceVault({
      ...financeVault,
      goals: nextGoals,
    })
    if (financeSelectedGoalId === goalId && nextGoals[0]) {
      setFinanceSelectedGoalId(nextGoals[0].id)
    }
    showToast('Target tabungan dihapus.')
  }

  // ============================================================================
  // PERSONAL QUEST CRUD HANDLERS
  // ============================================================================

  const handleTogglePersonal = (taskId: string, targetDateIso?: string) => {
    const todayIso = getLocalIsoDate()
    const dateIso = targetDateIso || todayIso
    if (dateIso > todayIso) {
      showToast('Quest mendatang belum saatnya dikerjakan (Hanya Lihat).')
      return
    }

    const target =
      personalTasks.find(
        (t) =>
          t.id === taskId &&
          (t.userId === currentUser.id ||
            !t.userId ||
            (currentUser.username && t.userId === currentUser.username) ||
            (currentUser.username && t.id.includes(currentUser.username)))
      ) || personalTasks.find((t) => t.id === taskId)
    if (!target) return

    const isTargetToday = dateIso === todayIso
    const wasDoneOnDate = Boolean(target.completedDates?.includes(dateIso))
    const nextDone = !wasDoneOnDate
    const unskipToken = `unskip:${dateIso}`

    const nextTasks = personalTasks.map((t) => {
      if (t.id !== taskId) return t
      const prevDates = new Set(t.completedDates || [])
      const prevSkipped = new Set(t.skippedDates || [])
      if (nextDone) {
        prevDates.add(dateIso)
        prevSkipped.delete(dateIso)
        prevSkipped.delete(unskipToken)
      } else {
        prevDates.delete(dateIso)
        if (dateIso < todayIso) {
          prevSkipped.add(unskipToken)
        }
      }
      const nextExercises =
        isTargetToday && !nextDone && Array.isArray(t.workoutExercises)
          ? t.workoutExercises.map((ex) => ({
              ...ex,
              sets: ex.sets.map((s) => (s.completed ? { ...s, completed: false } : s)),
            }))
          : t.workoutExercises
      return {
        ...t,
        done: prevDates.has(todayIso),
        skipped: prevSkipped.has(todayIso),
        completedDates: Array.from(prevDates),
        skippedDates: Array.from(prevSkipped),
        workoutExercises: nextExercises,
      }
    })

    setPersonalTasks(nextTasks)
    const updatedTask = nextTasks.find((t) => t.id === taskId)
    if (updatedTask) {
      saveCloudQuest(updatedTask, currentUser.username)
    }

    // UPDATE XP LANGSUNG PER QUEST (OTOMATIS SESUAI KATEGORI) + CEK DAILY FULL-CLEAR BONUS
    const taskXp = findCategory(target.category).xp
    const nextUserTodayTasks = nextTasks.filter(
      (t) =>
        (t.userId === currentUser.id ||
          !t.userId ||
          (currentUser.username && (t.userId === currentUser.username || t.id.includes(currentUser.username)))) &&
        isQuestForToday(t.schedule)
    )
    const wasAllClear = isDailyAllClearToday
    const isNowAllClear =
      nextUserTodayTasks.length >= MIN_QUESTS_FOR_DAILY_BONUS &&
      nextUserTodayTasks.every((t) => Boolean(t.completedDates?.includes(todayIso)))
    const bonusDelta = isTargetToday
      ? !wasAllClear && isNowAllClear
        ? DAILY_FULL_CLEAR_BONUS_XP
        : wasAllClear && !isNowAllClear
          ? -DAILY_FULL_CLEAR_BONUS_XP
          : 0
      : 0

    const xpDelta = (nextDone ? taskXp : -taskXp) + bonusDelta
    const nextXp = Math.max(0, effectiveXp + xpDelta)
    const nextBonusDates = isTargetToday
      ? isNowAllClear
        ? Array.from(new Set([...(currentUser.dailyBonusDates || []), todayIso]))
        : (currentUser.dailyBonusDates || []).filter((d) => d !== todayIso)
      : currentUser.dailyBonusDates || []

    setUsers((curr) =>
      curr.map((u) =>
        u.id === currentUser.id || (currentUser.username && u.username === currentUser.username)
          ? { ...u, xp: nextXp, dailyBonusDates: nextBonusDates }
          : u
      )
    )
    saveCloudProfile({ ...currentUser, xp: nextXp })

    if (!isTargetToday) {
      if (nextDone) {
        showToast(`Quest "${target.title}" ditandai selesai pada ${dateIso}! +${taskXp} XP 🎉`)
      } else {
        showToast(`Status selesai "${target.title}" pada ${dateIso} dibatalkan. (-${taskXp} XP)`)
      }
    } else if (nextDone && !wasAllClear && isNowAllClear) {
      showToast(`🎉 ALL CLEAR! "${target.title}" (+${taskXp} XP) + Bonus Harian (+${DAILY_FULL_CLEAR_BONUS_XP} XP)!`)
    } else if (nextDone) {
      showToast(`Quest "${target.title}" selesai! +${taskXp} XP (${findCategory(target.category).name}) 🎉`)
    } else if (wasAllClear && !isNowAllClear) {
      showToast(`Quest "${target.title}" dibatalkan. (-${taskXp} XP & Bonus Harian ditarik)`)
    } else {
      showToast(`Quest "${target.title}" dibatalkan. (-${taskXp} XP)`)
    }
  }

  const handleSkipPersonal = (taskId: string, targetDateIso?: string) => {
    const todayIso = getLocalIsoDate()
    const dateIso = targetDateIso || todayIso
    if (dateIso > todayIso) {
      showToast('Quest mendatang belum saatnya dikerjakan (Hanya Lihat).')
      return
    }

    const target =
      personalTasks.find(
        (t) =>
          t.id === taskId &&
          (t.userId === currentUser.id ||
            !t.userId ||
            (currentUser.username && t.userId === currentUser.username) ||
            (currentUser.username && t.id.includes(currentUser.username)))
      ) || personalTasks.find((t) => t.id === taskId)
    if (!target) return

    const isTargetToday = dateIso === todayIso
    const unskipToken = `unskip:${dateIso}`
    const wasDone = Boolean(target.completedDates?.includes(dateIso))
    const wasSkippedOnDate =
      dateIso < todayIso
        ? !wasDone && !Boolean(target.skippedDates?.includes(unskipToken))
        : Boolean(
            target.skippedDates?.includes(dateIso) ||
              (!Boolean(target.skippedDates?.includes(unskipToken)) &&
                isQuestTimeSkipped(target.targetTime, wasDone, target.schedule))
          )
    const nextSkipped = !wasSkippedOnDate

    const nextTasks = personalTasks.map((t) => {
      if (t.id !== taskId) return t
      const prevDates = new Set(t.completedDates || [])
      const prevSkipped = new Set(t.skippedDates || [])

      if (nextSkipped) {
        prevSkipped.add(dateIso)
        prevSkipped.delete(unskipToken)
        prevDates.delete(dateIso)
      } else {
        prevSkipped.delete(dateIso)
        if (dateIso <= todayIso) {
          prevSkipped.add(unskipToken)
        }
      }
      return {
        ...t,
        skipped: prevSkipped.has(todayIso),
        done: prevDates.has(todayIso),
        completedDates: Array.from(prevDates),
        skippedDates: Array.from(prevSkipped),
      }
    })

    setPersonalTasks(nextTasks)
    const updatedTask = nextTasks.find((t) => t.id === taskId)
    if (updatedTask) {
      saveCloudQuest(updatedTask, currentUser.username)
    }

    if (wasDone) {
      const taskXp = findCategory(target.category).xp
      const nextXp = Math.max(0, effectiveXp - taskXp)
      setUsers((curr) =>
        curr.map((u) =>
          u.id === currentUser.id || (currentUser.username && u.username === currentUser.username)
            ? { ...u, xp: nextXp }
            : u
        )
      )
      saveCloudProfile({ ...currentUser, xp: nextXp })
    }

    if (nextSkipped) {
      showToast(`Quest "${target.title}" dilewati (${isTargetToday ? 'Terskip hari ini' : dateIso}) ⏭`)
    } else {
      showToast(`Skip quest "${target.title}" dibatalkan. Sekarang bisa dikerjakan!`)
    }
  }

  const handleDeletePersonal = (taskId: string) => {
    setPersonalTasks((curr) => curr.filter((t) => t.id !== taskId))
    deleteCloudQuest(taskId)
    showToast('Quest pribadi dihapus.')
  }

  const handleToggleSealPersonal = (taskId: string) => {
    const target = personalTasks.find((t) => t.id === taskId)
    if (!target) return
    const nextSealed = !Boolean(target.isSealed)
    const updatedTask: PersonalTask = { ...target, isSealed: nextSealed }
    setPersonalTasks((curr) => curr.map((t) => (t.id === taskId ? updatedTask : t)))
    if (nextSealed && arrivedQuestAlert?.id === taskId) {
      setArrivedQuestAlert(null)
    }
    void saveCloudQuest(updatedTask, currentUser.username).then(() => {
      if (!nextSealed && updatedTask.targetTime) {
        void fetch('/api/push/schedule', {
          method: 'POST',
          keepalive: true,
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            userId: currentUser.id,
            username: currentUser.username,
          }),
        }).catch(() => {})
      }
    })
    showToast(
      nextSealed
        ? `"${target.title}" disegel ke Sealed Quests (XP & riwayat tetap aman).`
        : `"${target.title}" dibangkitkan (Awaken) ke jadwal aktif!`
    )
  }

