                                height: '54px',
                                borderRadius: '50%',
                                background: 'rgba(124, 58, 237, 0.85)',
                                backdropFilter: 'blur(10px)',
                                border: '2px solid rgba(103, 232, 249, 0.8)',
                                color: '#ffffff',
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'center',
                                cursor: 'pointer',
                                boxShadow: '0 0 20px rgba(124, 58, 237, 0.5)',
                                transition: 'opacity 0.2s, transform 0.2s',
